# ==============================================================================
# SECTION 5: THREAT INTELLIGENCE / IP REPUTATION ENGINE
# ==============================================================================

KNOWN_SUSPICIOUS_RANGES = ["185.220.", "45.33.", "89.248.", "194.26.", "91.240."]


class ThreatIntelEngine:
    """Heuristic IP reputation scoring — no external calls, fully offline-capable."""

    @staticmethod
    def _is_private(ip: str) -> bool:
        return ip.startswith(("10.", "192.168.")) or bool(re.match(r"^172\.(1[6-9]|2\d|3[01])\.", ip))

    def evaluate(self, ip: str) -> ThreatIntelResult:
        notes: List[str] = []
        score = 5

        if self._is_private(ip):
            notes.append("Address falls within RFC1918 private space — treat as internal asset.")
            return ThreatIntelResult(
                ip_address=ip, reputation_score=0, classification="Internal / Trusted",
                is_private=True, notes=notes,
            )

        if any(ip.startswith(prefix) for prefix in KNOWN_SUSPICIOUS_RANGES):
            score += 60
            notes.append("IP prefix matches a known suspicious/anonymization-associated range.")

        octets = ip.split(".")
        if len(octets) == 4 and octets[-1] in ("1", "254"):
            score += 5
            notes.append("Gateway-like host suffix observed.")

        score += random.randint(0, 15)  # simulated intel jitter for demo telemetry
        score = min(score, 100)

        if score >= 70:
            classification = "Malicious (High Confidence)"
        elif score >= 40:
            classification = "Suspicious"
        else:
            classification = "Likely Benign"

        return ThreatIntelResult(
            ip_address=ip, reputation_score=score, classification=classification,
            is_private=False, notes=notes or ["No adverse indicators found in local intel feed."],
        )


# ==============================================================================
# SECTION 6: LLM-POWERED DEEP TRIAGE ORCHESTRATOR
# ==============================================================================

class LLMTriageOrchestrator:
    def __init__(self, provider: str = "Offline / Local Rule Engine", api_key: Optional[str] = None,
                 model_name: Optional[str] = None, local_host: str = "http://localhost:11434"):
        self.provider = provider
        self.api_key = api_key
        self.local_host = local_host
        if model_name:
            self.model_name = model_name
        elif provider == "OpenAI":
            self.model_name = "gpt-4o"
        elif provider == "Anthropic":
            self.model_name = "claude-sonnet-4-5"
        else:
            self.model_name = "llama3"

    def _build_prompt(self, context_label: str, payload: str, score: float) -> str:
        return f"""
        SENTINEL AI TRIAGE REQUEST
        Context: {context_label}
        Risk Score: {score}/100
        Evidence: {payload}

        Perform a concise security triage. Respond with ONLY valid JSON matching:
        {{
            "threat_level": "Critical|High|Medium|Low",
            "attack_vector": "Brief classification",
            "impact_assessment": "Impact on systems / data",
            "actionable_remediation": ["Step 1", "Step 2", "Step 3"]
        }}
        """

    def execute_triage(self, context_label: str, payload: str, score: float) -> TriageReport:
        prompt = self._build_prompt(context_label, payload, score)
        self.last_error: Optional[str] = None  # set below if the live call fails and we fall back

        if self.provider == "Ollama (Local)":
            try:
                response = requests.post(
                    f"{self.local_host}/api/generate",
                    json={"model": self.model_name, "prompt": prompt, "format": "json", "stream": False},
                    timeout=10,
                )
                if response.status_code == 200:
                    data = json.loads(response.json().get("response", "{}"))
                    return TriageReport(**data)
                self.last_error = f"Ollama returned HTTP {response.status_code}"
            except Exception as e:
                self.last_error = f"Ollama request failed: {e}"

        elif self.provider == "OpenAI" and self.api_key and OpenAI:
            try:
                client = OpenAI(api_key=self.api_key)
                response = client.chat.completions.create(
                    model=self.model_name,
                    messages=[
                        {"role": "system", "content": "You are Sentinel AI, a defensive incident-response triage engine. Return ONLY JSON."},
                        {"role": "user", "content": prompt},
                    ],
                    response_format={"type": "json_object"},
                )
                data = json.loads(response.choices[0].message.content)
                return TriageReport(**data)
            except Exception as e:
                self.last_error = f"OpenAI request failed: {e}"

        elif self.provider == "Anthropic" and self.api_key and Anthropic:
            try:
                client = Anthropic(api_key=self.api_key)
                message = client.messages.create(
                    model=self.model_name,
                    max_tokens=500,
                    messages=[{"role": "user", "content": prompt}],
                )
                data = json.loads(message.content[0].text)
                return TriageReport(**data)
            except Exception as e:
                self.last_error = f"Anthropic request failed: {e}"
        elif self.provider in ("OpenAI", "Anthropic"):
            # Falls here when the specific provider branch above didn't run:
            # no API key entered, or the provider's SDK isn't installed.
            # Previously this case just fell through to the offline
            # fallback with no explanation at all.
            if not self.api_key:
                self.last_error = f"No {self.provider} API key was provided"
            elif (self.provider == "OpenAI" and OpenAI is None) or (self.provider == "Anthropic" and Anthropic is None):
                self.last_error = f"The {self.provider} Python SDK isn't installed in this environment"

        # Deterministic offline fallback so the app always returns a usable report.
        # Previously execute_triage() failed COMPLETELY SILENTLY on a live-provider
        # error (bad key, network down, rate limit) — the user would see a fully
        # formed-looking report and have no reason to suspect it wasn't real AI
        # analysis. self.last_error above lets the caller show what happened.
        level = "Critical" if score > 85 else "High" if score > 65 else "Medium" if score > 35 else "Low"
        return TriageReport(
            threat_level=level,
            attack_vector=f"Local Heuristic Match ({context_label})",
            impact_assessment="Potential unauthorized access, data exposure, or service disruption pending confirmation.",
            actionable_remediation=[
                "Isolate or rate-limit the source associated with this event.",
                "Review recent authentication and access logs for the affected asset.",
                "Escalate to on-call security engineer if score remains elevated after review.",
            ],
        )


# ==============================================================================
# SECTION 7: ACTIVE CONTAINMENT PLAYBOOKS (SIMULATED)
# ==============================================================================

@dataclass
class EnvironmentDeclaration:
    """A human's explicit statement of what kind of environment `target`
    is. This is the ONLY way a target's risk context becomes known to
    AutonomyBoundaryGuard — nothing in that class ever infers, guesses, or
    defaults this from the target's name, format, or any other signal."""
    target: str
    is_production: bool
    declared_by: str
    declared_at: str

    def is_stale(self, max_age_minutes: int = 480) -> bool:
        """A declaration doesn't stay valid forever — environments change
        (a test box today can become production tomorrow). Past
        `max_age_minutes` (default 8 hours), the guard treats it as if it
        were never declared, forcing a fresh confirmation rather than
        silently trusting an old assumption indefinitely."""
        try:
            declared_dt = datetime.strptime(self.declared_at, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            return True
        return (datetime.now() - declared_dt).total_seconds() > max_age_minutes * 60


@dataclass
class GovernorDecision:
    allowed: bool
    target: str
    action_tier: str
    reason: str
    required_human_action: str
    timestamp: str


class AutonomyBoundaryGuard:
    """
    Operationalizes one specific, narrow lesson from a real, disclosed
    incident (Anthropic, July 2026: Claude models operating during
    authorized security-testing engagements reasoned past ambiguous
    evidence about their environment and acted on their own conclusion
    without a human confirming first — see
    https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals).
    The failure wasn't malice or a capability gap — it was ambiguity
    getting resolved toward "proceed" instead of toward "stop and ask."
    This class makes that resolution direction structural rather than
    aspirational: for anything above pure read-only analysis, the default
    for "not yet explicitly declared" is ALWAYS the more restrictive
    interpretation. Nothing here infers permission from a target's name,
    a prior scan, or an LLM's own assessment of "this looks like a test
    box" — only an explicit, timestamped, attributed human declaration
    counts.

    This wraps AROUND — does not replace — the existing safeguards
    elsewhere in this app: AuthorizationManager answers "is this target
    in scope at all," AutoResponseEngine's circuit breaker answers "are
    we executing too fast." This answers a third, different question:
    "has a human explicitly confirmed the risk context of THIS class of
    action against THIS target, recently enough to still trust it." An
    authorized, rate-limited action against a target whose production
    status was never confirmed is exactly the gap those two don't cover.

    Every action in this entire app is already simulated — nothing here
    reaches real infrastructure. This guard is deliberately built anyway,
    because the discipline of stopping to confirm environment context
    before acting is the thing worth having in place BEFORE the day
    someone wires a simulated action to something real, not after.
    """

    ACTION_TIERS: Tuple[str, ...] = ("advisory", "simulated", "scoped_action")

    def __init__(self, persistence: Optional["SentinelPersistence"] = None) -> None:
        self._declarations: Dict[str, EnvironmentDeclaration] = {}
        self._decision_log: List[GovernorDecision] = []
        self.persistence = persistence

    def declare_environment(self, target: str, is_production: bool, declared_by: str) -> EnvironmentDeclaration:
        decl = EnvironmentDeclaration(
            target=target, is_production=is_production, declared_by=declared_by,
            declared_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        )
        self._declarations[target] = decl
        if self.persistence is not None:
            self.persistence.save_declaration(target, is_production, declared_by, decl.declared_at)
        return decl

    def restore_declaration(self, target: str, is_production: bool, declared_by: str,
                            declared_at: str) -> EnvironmentDeclaration:
        """Reconstructs a declaration with its ORIGINAL timestamp — for
        loading persisted declarations back in after a restart. Deliberately
        NOT the same as declare_environment(), which always stamps 'now':
        if restoring used declare_environment(), every declaration would
        look freshly-made after every app restart, silently defeating
        is_stale()'s whole purpose. A declaration made 10 hours ago must
        still read as 10 hours old after a restart, not reset to zero.
        Never writes back to persistence — it's restoring FROM there."""
        decl = EnvironmentDeclaration(
            target=target, is_production=is_production, declared_by=declared_by, declared_at=declared_at,
        )
        self._declarations[target] = decl
        return decl

    def load_from_persistence(self) -> int:
        """Restores every previously-declared environment from disk with
        original timestamps intact (via restore_declaration, never
        declare_environment) — so a declaration's staleness is judged
        against when a human ACTUALLY made it, not against when the app
        most recently restarted. Safe no-op when no persistence is set."""
        if self.persistence is None:
            return 0
        rows = self.persistence.load_declarations()
        for row in rows:
            self.restore_declaration(row["target"], row["is_production"], row["declared_by"], row["declared_at"])
        return len(rows)

    def _log(self, decision: GovernorDecision) -> GovernorDecision:
        self._decision_log.append(decision)
        return decision

    def check(self, action_tier: str, target: str, action_description: str = "") -> GovernorDecision:
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if action_tier not in self.ACTION_TIERS:
            return self._log(GovernorDecision(
                allowed=False, target=target, action_tier=action_tier,
                reason=f"Unknown action tier '{action_tier}' — unrecognized tiers are refused, not "
                      f"passed through with a default.",
                required_human_action=f"Use one of: {', '.join(self.ACTION_TIERS)}.", timestamp=now,
            ))

        if action_tier == "advisory":
            return self._log(GovernorDecision(
                allowed=True, target=target, action_tier=action_tier,
                reason="Advisory/read-only analysis is always allowed — no environment declaration needed.",
                required_human_action="", timestamp=now,
            ))

        decl = self._declarations.get(target)
        if decl is None or decl.is_stale():
            reason = (f"No environment declaration exists for '{target}'." if decl is None else
                     f"The declaration for '{target}' is stale (made {decl.declared_at}) and needs "
                     f"reconfirming.")
            return self._log(GovernorDecision(
                allowed=False, target=target, action_tier=action_tier,
                reason=f"{reason} Ambiguity resolves to BLOCKED, never to 'assume safe' — this is the "
                      f"specific asymmetry the incident this class references showed matters.",
                required_human_action=f"Call declare_environment() for '{target}' before this action can proceed.",
                timestamp=now,
            ))

        if decl.is_production and action_tier == "scoped_action":
            return self._log(GovernorDecision(
                allowed=False, target=target, action_tier=action_tier,
                reason=f"'{target}' is explicitly declared PRODUCTION by {decl.declared_by}. "
                      f"Scoped (non-simulated) actions against declared production are never "
                      f"auto-approved by this guard, regardless of any other authorization in place.",
                required_human_action="A human must take this specific action manually — this guard "
                                      "does not grant autonomous execution against declared production.",
                timestamp=now,
            ))

        return self._log(GovernorDecision(
            allowed=True, target=target, action_tier=action_tier,
            reason=f"'{target}' is declared {'production' if decl.is_production else 'non-production'} "
                  f"by {decl.declared_by} at {decl.declared_at}; {action_tier} actions are permitted "
                  f"once environment context is explicitly confirmed.",
            required_human_action="", timestamp=now,
        ))

    def get_decision_log(self) -> List[GovernorDecision]:
        return list(self._decision_log)

    def get_declarations(self) -> List[EnvironmentDeclaration]:
        return list(self._declarations.values())

    def blocked_count(self) -> int:
        return sum(1 for d in self._decision_log if not d.allowed)


class ActiveContainmentEngine:
    def __init__(self, webhook_url: Optional[str] = None):
        self.webhook_url = webhook_url
        self.action_history: List[Dict[str, Any]] = []

    def _record(self, action: Dict[str, Any]) -> Dict[str, Any]:
        self.action_history.append(action)
        if self.webhook_url:
            try:
                requests.post(self.webhook_url, json=action, timeout=3)
            except Exception:
                pass
        return action

    def block_ip_firewall(self, ip_address: str, duration_mins: int = 60) -> Dict[str, Any]:
        return self._record({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "BLOCK_IP", "target": ip_address, "status": "SUCCESS",
            "details": f"Added drop rule for {ip_address} (TTL: {duration_mins}m)",
        })

    def isolate_k8s_pod(self, target_asset: str) -> Dict[str, Any]:
        return self._record({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "ISOLATE_K8S_ASSET", "target": target_asset, "status": "SUCCESS",
            "details": f"Applied deny-all NetworkPolicy to workload deployment/{target_asset}",
        })

    def revoke_api_tokens(self, target_asset: str) -> Dict[str, Any]:
        return self._record({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "REVOKE_CREDENTIALS", "target": target_asset, "status": "SUCCESS",
            "details": f"Invalidated JWT service accounts and dynamic IAM keys for {target_asset}",
        })

    def quarantine_file(self, file_name: str) -> Dict[str, Any]:
        return self._record({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "QUARANTINE_FILE", "target": file_name, "status": "SUCCESS",
            "details": f"Moved {file_name} to isolated quarantine storage pending manual review.",
        })

    def force_password_reset(self, target_asset: str) -> Dict[str, Any]:
        return self._record({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "action": "FORCE_PASSWORD_RESET", "target": target_asset, "status": "SUCCESS",
            "details": f"Triggered mandatory credential rotation for accounts on {target_asset}",
        })

    def get_action_history(self) -> List[Dict[str, Any]]:
        return self.action_history


# ==============================================================================
# SECTION 8: REPORT GENERATION
# ==============================================================================

class ReportGenerator:
    @staticmethod
    def findings_to_dataframe(findings: List[VulnerabilityFinding]) -> pd.DataFrame:
        if not findings:
            return pd.DataFrame(columns=[
                "rule_id", "title", "severity", "cwe", "cvss_estimate",
                "file_name", "line_number", "matched_snippet",
            ])
        return pd.DataFrame([f.model_dump() for f in findings])

    @staticmethod
    def build_json_report(scan_name: str, findings: List[VulnerabilityFinding],
                           dep_findings: List[DependencyVuln]) -> str:
        report = {
            "report_name": scan_name,
            "generated_at": datetime.now().isoformat(),
            "summary": {
                "total_code_findings": len(findings),
                "total_dependency_findings": len(dep_findings),
                "by_severity": {
                    sev: len([f for f in findings if f.severity == sev])
                    for sev in ["Critical", "High", "Medium", "Low", "Info"]
                },
            },
            "code_findings": [f.model_dump() for f in findings],
            "dependency_findings": [d.model_dump() for d in dep_findings],
        }
        return json.dumps(report, indent=2)

    @staticmethod
    def build_sarif_report(findings: List[VulnerabilityFinding],
                            container_findings: Optional[List["ContainerFinding"]] = None,
                            tool_version: str = "1.0.0") -> str:
        """
        SARIF 2.1.0 export (https://docs.oasis-open.org/sarif/sarif/v2.1.0)
        of code findings + container/IaC findings — the format GitHub code
        scanning, Azure DevOps, and most CI security gates expect. This is
        the one comparison-table row ("CI / IDE / SARIF") this project had
        nothing for at all; every commercial competitor in the comparison
        has it.

        Deliberately scoped to `findings` (the rule-engine SAST results)
        and `container_findings` (Dockerfile/Compose/K8s checks) — both
        are static, rule-keyed detections with a stable rule_id/check_id,
        which is exactly what SARIF's rule-catalog model expects.
        Semantic/AI findings are explicitly NOT included: they're
        non-deterministic and can hallucinate (see the AI Semantic
        Reviewer tab's own warning), and SARIF consumers like GitHub code
        scanning treat every result as an asserted, stable finding tied to
        a fixed rule — mixing in non-deterministic output would misrepresent
        both what SARIF means and what that engine actually guarantees.
        """
        container_findings = container_findings or []
        sev_to_level = {"Critical": "error", "High": "error", "Medium": "warning",
                         "Low": "note", "Info": "note", "OK": "note", "Unknown": "warning"}
        sev_to_score = {"Critical": "9.0", "High": "7.5", "Medium": "5.0", "Low": "3.0", "Info": "1.0"}

        rules: Dict[str, Dict[str, Any]] = {}
        results: List[Dict[str, Any]] = []

        def _fingerprint(*parts: str) -> str:
            # Deliberately excludes line number: a finding's identity
            # shouldn't change just because unrelated code moved above it,
            # or GitHub code scanning will treat every line-shift as a
            # brand-new finding instead of tracking the same one.
            h = hashlib.sha256("|".join(parts).encode("utf-8", errors="ignore"))
            return h.hexdigest()[:16]

        for f in findings:
            if f.rule_id not in rules:
                rules[f.rule_id] = {
                    "id": f.rule_id,
                    "name": f.rule_id,
                    "shortDescription": {"text": f.title},
                    "fullDescription": {"text": f.description or f.title},
                    "help": {"text": f.remediation or "See finding details."},
                    "properties": {
                        "tags": ["security", f.cwe] if f.cwe else ["security"],
                        "cwe": f.cwe,
                        "security-severity": f"{f.cvss_estimate:.1f}",
                        "precision": f.confidence.lower() if f.confidence else "medium",
                    },
                    "defaultConfiguration": {"level": sev_to_level.get(f.severity, "warning")},
                }
            uri = f.file_name.replace("\\", "/").lstrip("/")
            line = max(1, f.line_number)
            result: Dict[str, Any] = {
                "ruleId": f.rule_id,
                "level": sev_to_level.get(f.severity, "warning"),
                "message": {"text": f.description or f.title},
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {"uri": uri},
                        "region": {"startLine": line},
                    }
                }],
                "partialFingerprints": {
                    "sentinelaiFingerprint/v1": _fingerprint(f.rule_id, uri, f.matched_snippet)
                },
                "properties": {"security-severity": f"{f.cvss_estimate:.1f}"},
            }
            if f.matched_snippet:
                result["locations"][0]["physicalLocation"]["region"]["snippet"] = {"text": f.matched_snippet}
            results.append(result)

        for c in container_findings:
            if c.check_id not in rules:
                rules[c.check_id] = {
                    "id": c.check_id,
                    "name": c.check_id,
                    "shortDescription": {"text": c.title},
                    "fullDescription": {"text": c.detail or c.title},
                    "help": {"text": c.recommendation or "See finding details."},
                    "properties": {
                        "tags": ["security", "container", c.category] if c.category else ["security", "container"],
                        "security-severity": sev_to_score.get(c.severity, "5.0"),
                        "precision": "medium",
                    },
                    "defaultConfiguration": {"level": sev_to_level.get(c.severity, "warning")},
                }
            uri = c.file_name.replace("\\", "/").lstrip("/")
            line = max(1, c.line_number)
            results.append({
                "ruleId": c.check_id,
                "level": sev_to_level.get(c.severity, "warning"),
                "message": {"text": c.detail or c.title},
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {"uri": uri},
                        "region": {"startLine": line},
                    }
                }],
                "partialFingerprints": {
                    "sentinelaiFingerprint/v1": _fingerprint(c.check_id, uri, c.title)
                },
                "properties": {"security-severity": sev_to_score.get(c.severity, "5.0")},
            })

        sarif_log = {
            "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
            "version": "2.1.0",
            "runs": [{
                "tool": {
                    "driver": {
                        "name": "SentinelAI",
                        "version": tool_version,
                        "rules": list(rules.values()),
                    }
                },
                "results": results,
            }],
        }
        return json.dumps(sarif_log, indent=2)


# ==============================================================================
# ==============================================================================
#  SEMANTIC TAINT ENGINE MODULE (embedded) — real AST-based interprocedural
#  vulnerability analysis for Python, wired into the dashboard below as a
#  dedicated "Semantic Scanner" tab, distinct from the regex-based
#  CodeVulnerabilityScanner used elsewhere in this file. See each class's
#  docstring for exact scope/limitations (this is disclosed, not hidden).
# ==============================================================================
# ==============================================================================

# ==============================================================================
# SECTION 1: ENUMS & STANDARDS MAPPING
# ==============================================================================

class Severity(str, Enum):
    CRITICAL = "Critical"
    HIGH = "High"
    MEDIUM = "Medium"
    LOW = "Low"
    INFO = "Info"


class Confidence(str, Enum):
    HIGH = "High"
    MEDIUM = "Medium"
    LOW = "Low"


@dataclass(frozen=True)
class StandardsMapping:
    cwe: str
    owasp_top10: str = ""
    owasp_asvs: str = ""
    capec: str = ""
    nist_ssdf: str = ""
    mitre_attack: str = ""  # left blank unless a genuine correspondence exists


# ==============================================================================
# SECTION 2: CORE DATA MODELS
# ==============================================================================

@dataclass
class PropagationStep:
    line: int
    code: str
    kind: str  # "function_entry" | "source" | "assignment" | "call" | "sink"
    function: str = ""


@dataclass
class CrossFileCandidate:
    """Recorded when the taint walker hits a call it can't resolve WITHIN
    the current file, but the call's arguments carry real taint — exactly
    the situation where a genuine vulnerability could be hiding behind a
    file boundary (`from utils import run_it; run_it(tainted_cmd)`, where
    utils.py is a separate file). Purely additive: this never changes
    single-file findings, it just remembers what got left on the table so
    a project-wide pass can optionally follow up on it."""
    resolved_name: str
    call_line: int
    caller_file: str
    caller_function: str
    per_arg_taint: List[Set[str]]  # index-aligned with the call's positional args
    path_so_far: List[PropagationStep]


@dataclass
class Finding:
    finding_id: str
    rule_id: str
    title: str
    vuln_class: str
    severity: str
    confidence: str
    standards: StandardsMapping
    file_name: str
    function_name: str
    sink_line: int
    evidence: str
    propagation_path: List[PropagationStep]
    impacted_functions: List[str]
    remediation: str
    suggested_fix: str
    engine: str = "semantic"  # "semantic" (AST/taint) vs "heuristic" (regex fallback)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "finding_id": self.finding_id,
            "rule_id": self.rule_id,
            "title": self.title,
            "vuln_class": self.vuln_class,
            "severity": self.severity,
            "confidence": self.confidence,
            "cwe": self.standards.cwe,
            "owasp_top10": self.standards.owasp_top10,
            "owasp_asvs": self.standards.owasp_asvs,
            "capec": self.standards.capec,
            "nist_ssdf": self.standards.nist_ssdf,
            "mitre_attack": self.standards.mitre_attack,
            "file_name": self.file_name,
            "function_name": self.function_name,
            "sink_line": self.sink_line,
            "evidence": self.evidence,
            "propagation_path": [
                {"line": s.line, "code": s.code, "kind": s.kind, "function": s.function}
                for s in self.propagation_path
            ],
            "impacted_functions": self.impacted_functions,
            "remediation": self.remediation,
            "suggested_fix": self.suggested_fix,
            "engine": self.engine,
        }


@dataclass
class TaintRule:
    """A structured rule object — sources/sinks/sanitizers/severity/CWE/confidence/remediation."""
    id: str
    title: str
