# ==============================================================================
#  MODULE: URL SECURITY HEADER SCANNER
#  Passive HTTP GET scan of any URL the user provides.
#  IMPORTANT: Only point this at systems you own or have written permission
#  to test. This tool makes real outbound network requests.
# ==============================================================================
# ==============================================================================

@dataclass
class HeaderFinding:
    header: str
    present: bool
    value: str
    severity: str
    recommendation: str


@dataclass
class URLScanResult:
    url: str
    reachable: bool
    https_enforced: bool
    status_code: int
    server_banner: str
    header_findings: List[HeaderFinding]
    overall_grade: str
    scan_time: str
    error: str = ""


class URLSecurityScanner:
    """
    Checks any URL the user explicitly provides for:
      - HTTPS enforcement
      - Missing/misconfigured security headers (CSP, HSTS, X-Frame-Options, etc.)
      - Information-leaking headers (Server, X-Powered-By, X-AspNet-Version)
      - CORS wildcard policy
      - HTTP redirect behaviour (shown for review, not followed automatically)

    All checks are read-only passive HTTP GET requests. The scanner never
    follows redirects automatically (allow_redirects=False) so it cannot be
    used as an SSRF relay. Grades A-F based on missing critical headers.
    """

    _REQUIRED: List[Dict[str, str]] = [
        {"header": "Content-Security-Policy", "severity": "High",
         "rec": "Add CSP: default-src 'self'; avoid 'unsafe-inline' and 'unsafe-eval'."},
        {"header": "Strict-Transport-Security", "severity": "High",
         "rec": "Add: Strict-Transport-Security: max-age=31536000; includeSubDomains"},
        {"header": "X-Frame-Options", "severity": "Medium",
         "rec": "Add: X-Frame-Options: DENY (or use CSP frame-ancestors 'none')."},
        {"header": "X-Content-Type-Options", "severity": "Medium",
         "rec": "Add: X-Content-Type-Options: nosniff"},
        {"header": "Referrer-Policy", "severity": "Low",
         "rec": "Add: Referrer-Policy: strict-origin-when-cross-origin"},
        {"header": "Permissions-Policy", "severity": "Low",
         "rec": "Add: Permissions-Policy: geolocation=(), microphone=(), camera=()"},
        {"header": "Cross-Origin-Opener-Policy", "severity": "Low",
         "rec": "Add: Cross-Origin-Opener-Policy: same-origin"},
        {"header": "Cross-Origin-Resource-Policy", "severity": "Low",
         "rec": "Add: Cross-Origin-Resource-Policy: same-origin"},
    ]

    _LEAK_HEADERS = ["Server", "X-Powered-By", "X-AspNet-Version",
                     "X-Generator", "X-Runtime", "X-Version"]

    def scan(self, url: str, timeout: int = 8) -> URLScanResult:
        import urllib.parse
        parsed = urllib.parse.urlparse(url)
        https_enforced = parsed.scheme == "https"
        scan_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        try:
            resp = requests.get(
                url, timeout=timeout, allow_redirects=False,
                headers={"User-Agent": "SentinelAI-SecurityScanner/1.0 (defensive-audit)"},
                verify=True,
            )
            status_code = resp.status_code
            resp_headers: Dict[str, str] = dict(resp.headers)
        except Exception as exc:
            return URLScanResult(
                url=url, reachable=False, https_enforced=https_enforced,
                status_code=0, server_banner="", header_findings=[],
                overall_grade="F", scan_time=scan_time, error=str(exc),
            )

        # Normalise header keys to lower-case for lookup
        lower_headers: Dict[str, str] = {k.lower(): v for k, v in resp_headers.items()}
        header_findings: List[HeaderFinding] = []

        # ── Required security headers ────────────────────────────────────────
        for rule in self._REQUIRED:
            h = rule["header"]
            val = lower_headers.get(h.lower(), "")
            present = bool(val)
            header_findings.append(HeaderFinding(
                header=h,
                present=present,
                value=val[:160] if val else "MISSING",
                severity="OK" if present else rule["severity"],
                recommendation="" if present else rule["rec"],
            ))

        # ── Information-leaking headers ──────────────────────────────────────
        server_banner = ""
        for lh in self._LEAK_HEADERS:
            val = lower_headers.get(lh.lower(), "")
            if val:
                if lh.lower() == "server":
                    server_banner = val
                header_findings.append(HeaderFinding(
                    header=lh, present=True, value=val[:160], severity="Low",
                    recommendation=f"Remove or obscure the '{lh}' header to prevent version fingerprinting.",
                ))

        # ── CORS wildcard ────────────────────────────────────────────────────
        cors = lower_headers.get("access-control-allow-origin", "")
        if cors == "*":
            header_findings.append(HeaderFinding(
                header="Access-Control-Allow-Origin", present=True, value=cors,
                severity="Medium",
                recommendation="Restrict CORS to explicitly trusted origins instead of '*'.",
            ))

        # ── HTTPS redirect check ─────────────────────────────────────────────
        if not https_enforced:
            header_findings.append(HeaderFinding(
                header="HTTPS Enforcement", present=False, value="HTTP only",
                severity="High",
                recommendation="Redirect all HTTP traffic to HTTPS and enable HSTS.",
            ))

        # ── Grade ─────────────────────────────────────────────────────────────
        missing_high = sum(1 for f in header_findings if f.severity == "High")
        missing_med = sum(1 for f in header_findings if f.severity == "Medium")
        if not https_enforced or missing_high >= 2:
            grade = "F"
        elif missing_high == 1:
            grade = "D"
        elif missing_med >= 2:
            grade = "C"
        elif missing_med == 1:
            grade = "B"
        else:
            grade = "A"

        return URLScanResult(
            url=url, reachable=True, https_enforced=https_enforced,
            status_code=status_code, server_banner=server_banner,
            header_findings=header_findings, overall_grade=grade,
            scan_time=scan_time,
        )


# ==============================================================================
# ==============================================================================
#  MODULE: LIVE FILE SYSTEM WATCHER  (v2 — multi-language, content-verified,
#  debounced, risk-scored, and wired directly into detection + response)
#
#  What changed from v1 and why each change is a real fix, not decoration:
#   - v1 only recognized `.py` files. Every language the pattern scanner now
#     covers (PHP/JS/Java/Go/Rust/C/C#/Ruby/Kotlin) was invisible to "live"
#     monitoring even though it was fully supported for on-demand scans.
#   - v1 treated every mtime bump as a real change. Editors, `touch`, and
#     some CI checkouts update mtime without changing content, which meant
#     the same unchanged file could be rescanned indefinitely. Now change
#     detection is content-hash-based (SHA-256), with mtime only used as a
#     cheap pre-filter to decide whether hashing is even worth doing.
#   - v1 had no debounce, so a rapid save-loop (autosave, formatter-on-save)
#     could queue the same path many times in a few seconds. Now each path
#     has a minimum re-scan interval.
#   - v1 never watched deletions and would happily try to open a path that
#     no longer existed. Deletions are now tracked explicitly, reported
#     rather than dispatched to a scanner that would just error, and
#     deliberately exempted from debounce (see LiveFileWatcher.drain_events)
#     since a file appearing and quickly vanishing is itself a signal worth
#     seeing, not edit-loop noise to suppress.
#   - v1 only listened for on_modified/on_created/on_deleted, which misses
#     every save from an editor that saves atomically (write to a temp file,
#     then rename over the target — vim and some VSCode setups do this).
#     Those produce a MOVE event, not a MODIFIED one, so v1's real-time mode
#     would silently miss such saves entirely. on_moved is now handled too.
#   - v1 silently swallowed the watchdog startup exception with a bare
#     `except: pass`, which hides genuinely useful information (permission
#     errors, inotify watch-limit exhaustion) from the person trying to
#     debug why "real-time" mode isn't active. The reason is now captured
#     and surfaced.
#   - v1 globbed noisy directories (.git, node_modules, venv, __pycache__,
#     build artifacts) on every poll, which is both slow and produces
#     findings on vendored/generated code nobody asked to scan. Excluded
#     by default now, same exclusion list used by both watchdog and
#     mtime-polling paths so behavior doesn't silently differ between them.
#   - v1's "live" scan only ran two of the six available detection engines
#     (semantic + regex) and never told any other tab about what it found —
#     a live-detected critical malware pattern or leaked secret would NOT
#     appear in the Exploit Chain Correlator or trigger Auto-Response
#     unless the person separately re-ran a full scan. Findings from a live
#     event now merge into the same session-state lists every other tab
#     reads, and the caller can opt into an immediate auto-response sweep —
#     this is what actually connects "detect fast" to "respond fast".
# ==============================================================================
# ==============================================================================

# Extensions this module recognizes, mapped to the language key the
# PatternScanner heuristic rules use. Python gets the dedicated AST/taint
# engine on top of this, everyone else gets the pattern scanner + malware +
# secrets, which is a strictly wider set of detectors run per live event
# than v1 ever ran.
LIVE_WATCH_EXTENSIONS: Dict[str, str] = {
    ".py": "python", ".php": "php", ".js": "javascript", ".jsx": "javascript",
    ".ts": "javascript", ".tsx": "javascript", ".java": "java", ".go": "go",
    ".rs": "rust", ".c": "c", ".h": "c", ".cs": "csharp", ".rb": "ruby",
    ".kt": "kotlin", ".kts": "kotlin",
    ".swift": "swift", ".scala": "scala", ".sc": "scala",  # added: extended_rules.py batch 1
    ".pl": "perl", ".pm": "perl", ".m": "objc", ".mm": "objc",  # added: batch 6
    ".ex": "elixir", ".exs": "elixir", ".lua": "lua", ".dart": "dart", ".ps1": "powershell",
}

# Directories excluded from both watchdog recursion (via glob filtering) and
# mtime-polling — vendored/generated/VCS content that would otherwise
# dominate scan volume with nothing actionable.
LIVE_WATCH_EXCLUDED_DIRS: FrozenSet[str] = frozenset({
    ".git", "node_modules", "__pycache__", ".venv", "venv", "env",
    "dist", "build", ".mypy_cache", ".pytest_cache", "vendor", "target",
    ".tox", "site-packages",
})

# Files above this size are skipped for live scanning — large generated
# files (bundled JS, vendored SQL dumps, etc.) provide poor scan value per
# CPU-second spent and are exactly the kind of thing that turns a "live"
# watcher into a laggy one.
LIVE_WATCH_MAX_FILE_BYTES = 1_000_000

# Minimum seconds between re-scans of the SAME path — protects against
# autosave/formatter-on-save loops re-triggering full multi-engine scans
# many times per second for a file that's still being actively edited.
LIVE_WATCH_DEBOUNCE_SECONDS = 2.0


def _live_watch_path_excluded(path: str) -> bool:
    parts = set(os.path.normpath(path).split(os.sep))
    return bool(parts & LIVE_WATCH_EXCLUDED_DIRS)


@dataclass
class LiveScanEvent:
    """One completed live-scan pass over a single changed file — this is
    the richer unit v2 produces in place of v1's bare file-path string."""
    file_name: str
    event_type: str          # "modified" | "created" | "deleted"
    timestamp: str
    language: str
    engines_run: List[str]
    semantic_count: int = 0
    pattern_count: int = 0
    malware_count: int = 0
    secret_count: int = 0
    critical_count: int = 0
    high_count: int = 0
    risk_score: float = 0.0  # 0-100, weighted by severity mix — the number
                              # the live risk timeline chart plots over time
    error: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return {
            "file": self.file_name, "event": self.event_type, "timestamp": self.timestamp,
            "language": self.language, "engines": ", ".join(self.engines_run),
            "semantic": self.semantic_count, "pattern": self.pattern_count,
            "malware": self.malware_count, "secrets": self.secret_count,
            "critical": self.critical_count, "high": self.high_count,
            "risk_score": round(self.risk_score, 1), "error": self.error,
        }


class _WatchHandler:
    """Minimal watchdog-compatible event handler that pushes (path, event_type)
    tuples into a thread-safe queue for created/modified/deleted events on
    recognized extensions, skipping excluded directories at the source
    rather than filtering them out later."""

    def __init__(self, q: "_queue_module.Queue") -> None:
        self._q = q

    def _accept(self, src: str, is_dir: bool) -> bool:
        if is_dir or not src:
            return False
        if os.path.splitext(src)[1] not in LIVE_WATCH_EXTENSIONS:
            return False
        if _live_watch_path_excluded(src):
            return False
        return True

    def on_modified(self, event: Any) -> None:
        src = getattr(event, "src_path", "")
        if self._accept(src, getattr(event, "is_directory", True)):
            self._q.put((src, "modified"))

    def on_created(self, event: Any) -> None:
        src = getattr(event, "src_path", "")
        if self._accept(src, getattr(event, "is_directory", True)):
            self._q.put((src, "created"))

    def on_deleted(self, event: Any) -> None:
        src = getattr(event, "src_path", "")
        if self._accept(src, getattr(event, "is_directory", True)):
            self._q.put((src, "deleted"))

    def on_moved(self, event: Any) -> None:
        """Atomic-save editors (vim, some VSCode configurations) write to a
        temp file and then RENAME it over the target — which fires a MOVE
        event with src_path=temp, dest_path=target, not a MODIFIED event.
        Without this handler, every save from those editors would be
        silently invisible to real-time watching: on_modified simply never
        fires for them. We only care about the destination — if it lands
        on a watched extension, treat it exactly like a content change."""
        dest = getattr(event, "dest_path", "")
        if self._accept(dest, getattr(event, "is_directory", True)):
            self._q.put((dest, "modified"))


class LiveFileWatcher:
    """
    Monitors a directory for source file changes across every language the
    pattern scanner supports (not just Python), verifies changes by content
    hash rather than trusting mtime alone, debounces rapid repeat saves,
    and hands back structured LiveScanEvent-ready change descriptors.

    Usage (called from Streamlit UI):
        watcher.start("/path/to/project")     # begins watching
        changes = watcher.drain_events()       # (path, event_type) pairs, deduped+debounced
        watcher.stop()                         # shuts down observer thread
    """

    def __init__(self) -> None:
        self._observer: Any = None
        self._q: "_queue_module.Queue" = _queue_module.Queue()
        self._watched_path: str = ""
        self._running: bool = False
        self._mtimes: Dict[str, float] = {}
        self._content_hashes: Dict[str, str] = {}
        self._last_scanned_at: Dict[str, float] = {}
        self._start_error: str = ""
        # Tracks whether a real observer thread is actually delivering
        # events, independent of the global WATCHDOG_AVAILABLE flag —
        # WATCHDOG_AVAILABLE only reflects whether the package *imported*
        # successfully; Observer()/schedule() can still fail at runtime
        # (permission errors, inotify watch-limit exhaustion, etc.), and
        # drain_events() needs to know the ACTUAL state to decide whether
        # to poll, not just whether the import worked.
        self._using_observer: bool = False

    def start(self, path: str) -> str:
        """Start watching `path`. Returns a status string."""
        if self._running:
            self.stop()

        if not os.path.isdir(path):
            return f"Path does not exist or is not a directory: {path}"

        self._watched_path = path
        self._q = _queue_module.Queue()
        self._start_error = ""
        self._using_observer = False

        if WATCHDOG_AVAILABLE:
            try:
                handler = _WatchHandler(self._q)
                self._observer = Observer()
                real_handler = FileSystemEventHandler()
                real_handler.on_modified = handler.on_modified  # type: ignore
                real_handler.on_created = handler.on_created    # type: ignore
                real_handler.on_deleted = handler.on_deleted    # type: ignore
                real_handler.on_moved = handler.on_moved        # type: ignore
                self._observer.schedule(real_handler, path, recursive=True)
                self._observer.daemon = True
                self._observer.start()
                self._running = True
                self._using_observer = True
                self._seed_hashes(path)  # pre-hash existing files so the first
                                          # real change is diffed against actual
                                          # content, not treated as new from nothing
                return (f"Watching {path} via watchdog (inotify/FSEvents) — real-time, "
                        f"{len(LIVE_WATCH_EXTENSIONS)} file types, content-hash verified")
            except Exception as exc:
                self._start_error = str(exc)
                self._observer = None  # fall through to mtime polling

        self._seed_mtimes(path)
        self._seed_hashes(path)
        self._running = True
        suffix = f" (watchdog failed to start: {self._start_error})" if self._start_error else ""
        return (f"Watching {path} via mtime polling (install `watchdog` for real-time events)"
                f"{suffix}")

    def _iter_watched_files(self, path: str):
        for root, dirs, files in os.walk(path):
            dirs[:] = [d for d in dirs if d not in LIVE_WATCH_EXCLUDED_DIRS]
            for fname in files:
                if os.path.splitext(fname)[1] in LIVE_WATCH_EXTENSIONS:
                    yield os.path.join(root, fname)

    def _hash_file(self, fp: str) -> Optional[str]:
        try:
            if os.path.getsize(fp) > LIVE_WATCH_MAX_FILE_BYTES:
                return None
            with open(fp, "rb") as fh:
                return hashlib.sha256(fh.read()).hexdigest()
        except OSError:
            return None

    def _seed_mtimes(self, path: str) -> None:
        for fp in self._iter_watched_files(path):
            try:
                self._mtimes[fp] = os.path.getmtime(fp)
            except OSError:
                pass

    def _seed_hashes(self, path: str) -> None:
        for fp in self._iter_watched_files(path):
            h = self._hash_file(fp)
            if h is not None:
                self._content_hashes[fp] = h

    def _poll_mtimes(self) -> List[Tuple[str, str]]:
        changed: List[Tuple[str, str]] = []
        if not self._watched_path:
            return changed
        seen: Set[str] = set()
        for fp in self._iter_watched_files(self._watched_path):
            seen.add(fp)
            try:
                mt = os.path.getmtime(fp)
            except OSError:
                continue
            if fp not in self._mtimes or self._mtimes[fp] < mt:
                self._mtimes[fp] = mt
                event_type = "created" if fp not in self._content_hashes else "modified"
                changed.append((fp, event_type))
        # anything previously tracked but no longer on disk was deleted
        for fp in list(self._content_hashes.keys()):
            if fp.startswith(self._watched_path) and fp not in seen:
                changed.append((fp, "deleted"))
                self._content_hashes.pop(fp, None)
                self._mtimes.pop(fp, None)
        return changed

    def _content_actually_changed(self, fp: str, event_type: str) -> bool:
        """The core fix over v1: confirms a real content change via hash
        before letting an event through, rather than trusting the
        filesystem event (or mtime bump) at face value."""
        if event_type == "deleted":
            self._content_hashes.pop(fp, None)
            return True
        new_hash = self._hash_file(fp)
        if new_hash is None:
            return False  # unreadable or over the size cap — skip, don't crash the caller
        old_hash = self._content_hashes.get(fp)
        self._content_hashes[fp] = new_hash
        return old_hash != new_hash

    def _is_debounced(self, fp: str) -> bool:
        """Pure check, no side effect — separated from marking so an event
        that turns out NOT to be a genuine content change (e.g. an
        mtime-only touch) can never consume the debounce window for a
        real change that follows shortly after."""
        last = self._last_scanned_at.get(fp, 0.0)
        return (time.time() - last) < LIVE_WATCH_DEBOUNCE_SECONDS

    def _mark_scanned(self, fp: str) -> None:
        self._last_scanned_at[fp] = time.time()

    def drain_events(self) -> List[Tuple[str, str]]:
        """Returns deduped, content-verified, debounced (path, event_type)
        pairs ready to hand to a scanner. This is the v2 replacement for
        v1's drain(); each entry has already been confirmed to represent a
        genuine content change, not just a filesystem timestamp touch.

        Deletions are deliberately never debounced: a file that appears
        and quickly disappears again (e.g. a dropper cleaning up after
        itself) is a discrete, security-relevant event in its own right,
        not edit-loop noise — debounce logic exists to collapse rapid
        re-saves of the SAME kind of event, not to filter out a different
        kind of event that happens to land in the same time window.
        """
        raw: Dict[str, str] = {}  # path -> latest event_type seen this drain
        while not self._q.empty():
            try:
                fp, event_type = self._q.get_nowait()
                raw[fp] = event_type
            except Exception:
                break
        if not self._using_observer:
            for fp, event_type in self._poll_mtimes():
                raw[fp] = event_type

        confirmed: List[Tuple[str, str]] = []
        for fp, event_type in raw.items():
            if event_type == "deleted":
                self._content_hashes.pop(fp, None)
                self._last_scanned_at.pop(fp, None)
                confirmed.append((fp, event_type))
                continue
            if not self._content_actually_changed(fp, event_type):
                continue  # mtime moved but content is identical — never touches debounce state
            if self._is_debounced(fp):
                continue  # genuine change, but arrived within a prior genuine change's debounce window
            self._mark_scanned(fp)
            confirmed.append((fp, event_type))
        return confirmed

    def drain(self) -> List[str]:
        """Backward-compatible path-only view of drain_events()."""
        return [fp for fp, _ in self.drain_events()]

    def stop(self) -> None:
        if self._observer is not None:
            try:
                self._observer.stop()
                self._observer.join(timeout=3)
            except Exception:
                pass
        self._observer = None
        self._running = False
        self._using_observer = False
        self._watched_path = ""

    @property
    def is_running(self) -> bool:
        return self._running

    @property
    def watched_path(self) -> str:
        return self._watched_path

    @property
    def start_error(self) -> str:
        return self._start_error


class LiveScanOrchestrator:
    """
    Runs every applicable detection engine against a single live-changed
    file and produces a LiveScanEvent — this is the piece that makes the
    watcher's output as thorough as an on-demand full scan, instead of the
    v1 behavior of only running two of six available engines.

    Deliberately takes the already-instantiated engine objects rather than
    constructing its own, so live scanning shares the exact same rule set,
    custom rules, and confidence calibration as every other tab in the app
    — a finding detected live and a finding detected on-demand are the same
    finding, not two different code paths that can silently drift apart.
    """

    def __init__(self, semantic_scanner: Any, code_scanner: Any, pattern_scanner: Any,
                 malware_scanner: Any, entropy_scanner: Any) -> None:
        self.semantic_scanner = semantic_scanner
        self.code_scanner = code_scanner
        self.pattern_scanner = pattern_scanner
        self.malware_scanner = malware_scanner
        self.entropy_scanner = entropy_scanner

    @staticmethod
    def _read_safely(fp: str) -> Optional[str]:
        try:
            if os.path.getsize(fp) > LIVE_WATCH_MAX_FILE_BYTES:
                return None
            with open(fp, "rb") as fh:
                raw = fh.read()
            if b"\x00" in raw[:8192]:
                return None  # binary file — nothing to scan
            return raw.decode("utf-8", errors="ignore")
        except OSError:
            return None

    @staticmethod
    def _risk_score(critical: int, high: int, medium: int, low: int) -> float:
        """Weighted 0-100 risk score for a single scan event — heavier
        weight on critical/high so the live risk timeline actually spikes
        on things worth noticing rather than drifting up from Low-severity
        noise, while still being bounded rather than unbounded."""
        raw = critical * 25 + high * 10 + medium * 3 + low * 1
        return min(100.0, float(raw))

    def scan_event(self, fp: str, event_type: str) -> LiveScanEvent:
        timestamp = datetime.now().strftime("%H:%M:%S")
        ext = os.path.splitext(fp)[1]
        language = LIVE_WATCH_EXTENSIONS.get(ext, "unknown")

        if event_type == "deleted":
            return LiveScanEvent(file_name=fp, event_type="deleted", timestamp=timestamp,
                                 language=language, engines_run=[])

        content = self._read_safely(fp)
        if content is None:
            return LiveScanEvent(file_name=fp, event_type=event_type, timestamp=timestamp,
                                 language=language, engines_run=[],
                                 error="File unreadable, binary, or over the live-scan size cap")

        engines_run: List[str] = []
        semantic_findings: List[Any] = []
        pattern_findings: List[Any] = []
        malware_findings: List[Any] = []
        secret_findings: List[Any] = []
        evasion_findings: List[Any] = []

        try:
            if language == "python":
                semantic_findings = self.semantic_scanner.analyze_python(fp, content)
                engines_run.append("semantic (AST/taint)")
                pattern_findings = self.code_scanner.scan_text(fp, content)
                engines_run.append("regex")
                evasion_findings = scan_for_evasion(fp, content)
                if evasion_findings:
                    engines_run.append("evasion")
            elif language != "unknown":
                pattern_findings = self.pattern_scanner.scan(fp, content, language=language)
                engines_run.append(f"heuristic ({language})")

            malware_findings = self.malware_scanner.scan(fp, content)
            engines_run.append("malware")
            secret_findings = self.entropy_scanner.scan(fp, content)
            engines_run.append("secrets")
        except Exception as exc:
            return LiveScanEvent(file_name=fp, event_type=event_type, timestamp=timestamp,
                                 language=language, engines_run=engines_run,
                                 error=f"Scan error: {exc}")

        all_findings = list(semantic_findings) + list(pattern_findings) + list(malware_findings) + list(evasion_findings)
        sev_counts = {"Critical": 0, "High": 0, "Medium": 0, "Low": 0}
        for f in all_findings:
            sev = getattr(f, "severity", "Low")
            if sev in sev_counts:
                sev_counts[sev] += 1
        for s in secret_findings:
            if s.severity in sev_counts:
                sev_counts[s.severity] += 1

        risk = self._risk_score(sev_counts["Critical"], sev_counts["High"],
                                sev_counts["Medium"], sev_counts["Low"])

        event = LiveScanEvent(
            file_name=fp, event_type=event_type, timestamp=timestamp, language=language,
            engines_run=engines_run, semantic_count=len(semantic_findings) + len(evasion_findings),
            pattern_count=len(pattern_findings), malware_count=len(malware_findings),
            secret_count=len(secret_findings), critical_count=sev_counts["Critical"],
            high_count=sev_counts["High"], risk_score=risk,
        )
        # Attach the raw finding objects so the caller can merge them into
        # global session state (exploit-chain correlation, auto-response,
        # reporting) — this is what makes a live detection visible
        # everywhere else in the app instead of only in this one tab.
        event._raw_semantic = semantic_findings + evasion_findings  # type: ignore[attr-defined]
        event._raw_pattern = pattern_findings         # type: ignore[attr-defined]
        event._raw_malware = malware_findings         # type: ignore[attr-defined]
        event._raw_secrets = secret_findings          # type: ignore[attr-defined]
        return event



# ==============================================================================
# ==============================================================================
#  MODULE: ENTROPY-BASED SECRETS SCANNER
#  Uses Shannon entropy to find hardcoded secrets regardless of variable name.
#  Complements the regex-based SEC-009/SEC-010/SEC-011 rules by catching
#  secrets that don't match known naming patterns.
# ==============================================================================
# ==============================================================================

@dataclass
class SecretFinding:
    file_name: str
    line_number: int
    snippet: str
    entropy: float
    secret_type: str
    severity: str
    confidence: str
    recommendation: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "file_name": self.file_name, "line_number": self.line_number,
            "snippet": self.snippet, "entropy": round(self.entropy, 3),
            "secret_type": self.secret_type, "severity": self.severity,
            "confidence": self.confidence, "recommendation": self.recommendation,
        }


class EntropySecretsScanner:
    """
    Finds high-entropy string literals in source code that are likely
    hardcoded secrets (API keys, tokens, private keys, passwords).

    Approach:
      1. Walk the AST of Python files extracting all string literals.
      2. Apply Shannon entropy to each string of length >= min_length.
      3. Flag strings above the entropy threshold, with confidence
         scaled by length and entropy score.
      4. Additionally run regex patterns for known secret formats
         (AWS keys, GCP service account JSON, private key PEM blocks,
         Bearer tokens, base64-encoded blobs) across any file type.

    Shannon entropy H(X) = -Σ p(x) * log2(p(x))
    A random 32-char Base64 string scores ~5.8 bits/char.
    Natural English text scores ~3.5 bits/char.
    Threshold of 4.5 provides good separation in practice.
    """

    BASE64_CHARS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
    HEX_CHARS = set("0123456789abcdefABCDEF")

    SECRET_REGEX_PATTERNS: List[Dict[str, Any]] = [
        {"name": "AWS Access Key ID",        "pattern": r"AKIA[0-9A-Z]{16}", "severity": "Critical"},
        {"name": "AWS Secret Access Key",     "pattern": r"(?i)aws.{0,20}secret.{0,20}['\"][0-9a-zA-Z/+]{40}['\"]", "severity": "Critical"},
        {"name": "GCP API Key",               "pattern": r"AIza[0-9A-Za-z\-_]{35}", "severity": "Critical"},
        {"name": "GitHub Personal Token",     "pattern": r"ghp_[0-9a-zA-Z]{36}", "severity": "Critical"},
        {"name": "GitHub OAuth Token",        "pattern": r"gho_[0-9a-zA-Z]{36}", "severity": "Critical"},
        {"name": "GitHub Actions Token",      "pattern": r"ghs_[0-9a-zA-Z]{36}", "severity": "Critical"},
        {"name": "Slack Bot Token",           "pattern": r"xoxb-[0-9]{11}-[0-9]{11}-[0-9a-zA-Z]{24}", "severity": "High"},
        {"name": "Slack User Token",          "pattern": r"xoxp-[0-9]{11}-[0-9]{11}-[0-9]{11}-[0-9a-zA-Z]{32}", "severity": "High"},
        {"name": "Stripe Secret Key",         "pattern": r"sk_live_[0-9a-zA-Z]{24}", "severity": "Critical"},
        {"name": "Stripe Publishable Key",    "pattern": r"pk_live_[0-9a-zA-Z]{24}", "severity": "Medium"},
        {"name": "Twilio Account SID",        "pattern": r"AC[a-z0-9]{32}", "severity": "High"},
        {"name": "Twilio Auth Token",         "pattern": r"(?i)twilio.{0,10}[0-9a-f]{32}", "severity": "High"},
        {"name": "SendGrid API Key",          "pattern": r"SG\.[0-9a-zA-Z\-_]{22}\.[0-9a-zA-Z\-_]{43}", "severity": "High"},
        {"name": "Mailgun API Key",           "pattern": r"key-[0-9a-zA-Z]{32}", "severity": "High"},
        {"name": "NPM Auth Token",            "pattern": r"npm_[0-9a-zA-Z]{36}", "severity": "High"},
        {"name": "PyPI API Token",            "pattern": r"pypi-[0-9a-zA-Z\-_]{40,}", "severity": "High"},
        {"name": "Private Key PEM Block",     "pattern": r"-----BEGIN (RSA |EC |OPENSSH |)PRIVATE KEY-----", "severity": "Critical"},
        {"name": "JWT Token",                 "pattern": r"eyJ[0-9a-zA-Z\-_]+\.eyJ[0-9a-zA-Z\-_]+\.[0-9a-zA-Z\-_]+", "severity": "Medium"},
        {"name": "Generic Bearer Token",      "pattern": r"(?i)bearer\s+[0-9a-zA-Z\-_\.]{20,}", "severity": "Medium"},
        {"name": "Heroku API Key",            "pattern": r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", "severity": "Medium"},
        {"name": "Azure Storage Key",         "pattern": r"DefaultEndpointsProtocol=https;AccountName=", "severity": "High"},
        {"name": "Google OAuth Secret",       "pattern": r"[0-9]+-[0-9a-zA-Z_]{32}\.apps\.googleusercontent\.com", "severity": "High"},
        {"name": "SSH Private Key",           "pattern": r"-----BEGIN OPENSSH PRIVATE KEY-----", "severity": "Critical"},
        {"name": "PGP Private Key",           "pattern": r"-----BEGIN PGP PRIVATE KEY BLOCK-----", "severity": "Critical"},
        {"name": "Database URL with creds",   "pattern": r"(?i)(postgres|mysql|mongodb|redis)://[^:]+:[^@]+@", "severity": "Critical"},
        {"name": "Hardcoded password kwarg",  "pattern": r"(?i)password\s*=\s*['\"][^'\"]{6,}['\"]", "severity": "High"},
        {"name": "Hardcoded secret kwarg",    "pattern": r"(?i)secret\s*=\s*['\"][^'\"]{8,}['\"]", "severity": "High"},
    ]

    def __init__(self, entropy_threshold: float = 4.5, min_length: int = 16):
        self.entropy_threshold = entropy_threshold
        self.min_length = min_length
        self._compiled = [(r, re.compile(r["pattern"])) for r in self.SECRET_REGEX_PATTERNS]

    @staticmethod
    def shannon_entropy(s: str) -> float:
        if not s:
            return 0.0
        counts: Dict[str, int] = {}
        for ch in s:
            counts[ch] = counts.get(ch, 0) + 1
        length = len(s)
        return -sum((c / length) * math.log2(c / length) for c in counts.values())

    def _char_set_label(self, s: str) -> str:
        chars = set(s)
        if chars.issubset(self.HEX_CHARS):
            return "hex"
        if chars.issubset(self.BASE64_CHARS):
            return "base64"
        return "mixed"

    def scan_python_ast(self, file_name: str, content: str) -> List[SecretFinding]:
        findings: List[SecretFinding] = []
        try:
            tree = ast.parse(content)
        except SyntaxError:
            return findings

        lines = content.splitlines()
        for node in ast.walk(tree):
            if not isinstance(node, ast.Constant) or not isinstance(node.value, str):
                continue
            s = node.value
            if len(s) < self.min_length:
                continue
            entropy = self.shannon_entropy(s)
            if entropy < self.entropy_threshold:
                continue

            charset = self._char_set_label(s)
            if entropy >= 5.5:
                conf, sev = "High", "Critical"
            elif entropy >= 5.0:
                conf, sev = "Medium", "High"
            else:
                conf, sev = "Low", "Medium"

            line_no = getattr(node, "lineno", 0)
            snippet = lines[line_no - 1].strip()[:120] if 0 < line_no <= len(lines) else s[:60]
            findings.append(SecretFinding(
                file_name=file_name, line_number=line_no,
                snippet=snippet, entropy=entropy,
                secret_type=f"High-entropy {charset} string (len={len(s)})",
                severity=sev, confidence=conf,
                recommendation="Move this value to an environment variable or a secrets manager "
                               "(e.g. AWS Secrets Manager, HashiCorp Vault, Azure Key Vault). "
                               "Rotate the secret immediately if it has been committed to source control.",
            ))
        return findings

    def scan_regex(self, file_name: str, content: str) -> List[SecretFinding]:
        findings: List[SecretFinding] = []
        lines = content.splitlines()
        for rule, compiled in self._compiled:
            for match in compiled.finditer(content):
                line_no = content[: match.start()].count("\n") + 1
                snippet = lines[line_no - 1].strip()[:120] if 0 < line_no <= len(lines) else match.group(0)[:80]
                entropy = self.shannon_entropy(match.group(0))
                findings.append(SecretFinding(
                    file_name=file_name, line_number=line_no, snippet=snippet,
                    entropy=entropy, secret_type=rule["name"],
                    severity=rule["severity"], confidence="High",
                    recommendation=f"Revoke and rotate the exposed {rule['name']} immediately. "
                                   "Store it in a secrets manager and load via environment variable at runtime.",
                ))
        return findings

    def scan(self, file_name: str, content: str) -> List[SecretFinding]:
        all_findings = self.scan_regex(file_name, content)
        if file_name.endswith(".py"):
            all_findings += self.scan_python_ast(file_name, content)
        seen: Set[Tuple[str, int]] = set()
        deduped: List[SecretFinding] = []
        for f in all_findings:
            key = (f.file_name, f.line_number)
            if key not in seen:
                seen.add(key)
                deduped.append(f)
        return deduped


# ==============================================================================
# ==============================================================================
#  MODULE: JWT ANALYZER
#  Decodes and security-audits JWT tokens without verifying signatures
#  (no secret needed). Flags algorithm confusion, missing claims, weak algs.
# ==============================================================================
# ==============================================================================

@dataclass
class JWTIssue:
    issue_id: str
    severity: str
    title: str
    detail: str
    recommendation: str

@dataclass
class JWTAnalysisResult:
    raw_token: str
    header: Dict[str, Any]
    payload: Dict[str, Any]
    issues: List[JWTIssue]
    overall_risk: str
    is_expired: bool
    expiry_str: str

class JWTAnalyzer:
    """
    Decodes a JWT (header + payload only — signature is NOT verified here,
    as that requires the secret/key) and audits it for common weaknesses:
      - Algorithm set to 'none' (CVE-class: signature bypass)
      - Weak symmetric algorithms (HS256 with short secrets is guessable)
      - No expiry (exp) claim — tokens that never expire
      - No issued-at (iat) claim
      - No audience (aud) / issuer (iss) claims (replay risk)
      - Sensitive PII in payload (emails, passwords, SSNs)
      - Already-expired tokens still being used
    """

    WEAK_ALGORITHMS: Set[str] = {"none", "HS1", "RS1", ""}
    PREFERRED_ALGORITHMS: Set[str] = {"RS256", "RS384", "RS512", "ES256", "ES384", "ES512", "EdDSA"}

    def _b64_decode(self, segment: str) -> Dict[str, Any]:
        segment += "=" * (-len(segment) % 4)
        try:
            decoded = _base64.urlsafe_b64decode(segment)
            return json.loads(decoded)
        except Exception:
            return {}

    def analyze(self, token: str) -> Optional[JWTAnalysisResult]:
        token = token.strip()
        parts = token.split(".")
        if len(parts) != 3:
            return None

        header = self._b64_decode(parts[0])
        payload = self._b64_decode(parts[1])
        if not header:
            return None

        issues: List[JWTIssue] = []
        alg = str(header.get("alg", "")).strip()

        # ── Algorithm checks ────────────────────────────────────────────────
        if alg.lower() == "none":
            issues.append(JWTIssue(
                issue_id="JWT-001", severity="Critical",
                title="Algorithm set to 'none' — signature verification bypass",
                detail="A JWT with alg='none' carries no signature. Any server that accepts "
                       "it without checking the algorithm allows complete token forgery.",
                recommendation="Explicitly whitelist accepted algorithms (e.g. RS256 only). "
                               "Never accept 'none' in production.",
            ))
        elif alg in self.WEAK_ALGORITHMS:
            issues.append(JWTIssue(
                issue_id="JWT-002", severity="High",
                title=f"Weak or deprecated algorithm: {alg}",
                detail=f"The algorithm '{alg}' is considered weak or deprecated.",
                recommendation="Use RS256, ES256, or EdDSA (asymmetric) in preference to "
                               "symmetric HS256, which requires sharing the secret.",
            ))
        elif alg not in self.PREFERRED_ALGORITHMS and alg:
            issues.append(JWTIssue(
                issue_id="JWT-003", severity="Medium",
                title=f"Non-recommended algorithm: {alg}",
                detail=f"'{alg}' is not in the preferred set {self.PREFERRED_ALGORITHMS}.",
                recommendation="Prefer RS256 or ES256 for new systems.",
            ))

        # ── Claim checks ────────────────────────────────────────────────────
        now = time.time()
        is_expired = False
        expiry_str = "No expiry set"

        if "exp" not in payload:
            issues.append(JWTIssue(
                issue_id="JWT-004", severity="High",
                title="Missing 'exp' claim — token never expires",
                detail="Without an expiry claim, a stolen token is valid indefinitely.",
                recommendation="Always set 'exp' to a short-lived value (e.g. 15 minutes for "
                               "access tokens, 7 days for refresh tokens).",
            ))
        else:
            exp = payload["exp"]
            expiry_str = datetime.utcfromtimestamp(exp).strftime("%Y-%m-%d %H:%M:%S UTC")
            if exp < now:
                is_expired = True
                issues.append(JWTIssue(
                    issue_id="JWT-005", severity="Medium",
                    title="Token is expired",
                    detail=f"exp={expiry_str} is in the past. If this token is still being accepted "
                           "by a server, that server is not enforcing expiry.",
                    recommendation="Ensure the server rejects tokens past their 'exp' claim.",
                ))

        if "iat" not in payload:
            issues.append(JWTIssue(
                issue_id="JWT-006", severity="Low",
                title="Missing 'iat' (issued-at) claim",
                detail="Without 'iat', it is impossible to determine when the token was issued "
                       "or implement max-age policies.",
                recommendation="Always set 'iat' to the current Unix timestamp at issuance.",
            ))

        if "iss" not in payload:
            issues.append(JWTIssue(
                issue_id="JWT-007", severity="Low",
                title="Missing 'iss' (issuer) claim",
                detail="Without 'iss', tokens from different issuers may be accepted interchangeably.",
                recommendation="Set 'iss' to a unique issuer identifier and validate it server-side.",
            ))

        if "aud" not in payload:
            issues.append(JWTIssue(
                issue_id="JWT-008", severity="Low",
                title="Missing 'aud' (audience) claim",
                detail="Without 'aud', a token issued for one service may be replayed against another.",
                recommendation="Set 'aud' to the intended recipient service and validate it.",
            ))

        # ── Sensitive data in payload ────────────────────────────────────────
        sensitive_keys = {"password", "passwd", "pwd", "secret", "ssn", "credit_card",
                          "card_number", "cvv", "pin", "private_key"}
        for key in payload:
            if key.lower() in sensitive_keys:
                issues.append(JWTIssue(
                    issue_id="JWT-009", severity="High",
                    title=f"Sensitive field '{key}' in JWT payload",
                    detail="JWT payloads are base64-encoded, not encrypted. Anyone with the "
                           "token can read this field.",
                    recommendation=f"Remove '{key}' from the JWT payload. Store sensitive data "
                                   "server-side and reference it by a non-sensitive identifier.",
                ))

        # ── kid header injection risk ────────────────────────────────────────
        kid = header.get("kid", "")
        if isinstance(kid, str) and any(c in kid for c in ["'", '"', ";", "--", "/"]):
            issues.append(JWTIssue(
                issue_id="JWT-010", severity="Critical",
                title="Suspicious 'kid' header — possible SQL/path injection",
                detail=f"The 'kid' value '{kid[:60]}' contains characters that suggest "
                       "injection into a database key lookup or file-system path.",
                recommendation="Validate the 'kid' header against a strict allowlist of "
                               "known key identifiers before using it to look up a key.",
            ))

        # ── Overall risk ─────────────────────────────────────────────────────
        sev_weights = {"Critical": 4, "High": 3, "Medium": 2, "Low": 1}
        max_sev = max((sev_weights.get(i.severity, 0) for i in issues), default=0)
        overall = {4: "Critical", 3: "High", 2: "Medium", 1: "Low", 0: "Clean"}.get(max_sev, "Clean")

        return JWTAnalysisResult(
            raw_token=token[:40] + "...",
            header=header, payload=payload, issues=issues,
            overall_risk=overall, is_expired=is_expired, expiry_str=expiry_str,
        )


# ==============================================================================
# ==============================================================================
#  MODULE: SSL/TLS CERTIFICATE ANALYZER
#  Checks TLS configuration for any host:port the user provides.
#  Read-only — makes a standard TLS handshake and inspects the certificate.
# ==============================================================================
# ==============================================================================

@dataclass
class SSLFinding:
    check: str
    severity: str
    result: str
    recommendation: str

@dataclass
class SSLAnalysisResult:
    host: str
    port: int
    reachable: bool
    cert_subject: str
    cert_issuer: str
    not_before: str
    not_after: str
    days_until_expiry: int
    protocol_version: str
    cipher_suite: str
    findings: List[SSLFinding]
    overall_grade: str
    error: str = ""

class SSLCertAnalyzer:
    """
    Connects to any host:port the user specifies, performs a TLS handshake,
    and inspects:
      - Certificate validity period (expiry countdown)
      - Self-signed vs. CA-issued
      - Minimum TLS protocol version negotiated
      - Cipher suite strength
      - Subject Alternative Names present / CN match
      - Certificate chain length

    Never sends or receives application data — only the TLS handshake.
    Only scan hosts you own or have permission to test.
    """

    DEPRECATED_PROTOCOLS: Set[str] = {"SSLv2", "SSLv3", "TLSv1", "TLSv1.1"}
    WEAK_CIPHERS: Set[str] = {"RC4", "DES", "3DES", "MD5", "EXPORT", "NULL", "anon"}

    def analyze(self, host: str, port: int = 443, timeout: int = 8) -> SSLAnalysisResult:
        findings: List[SSLFinding] = []

        try:
            ctx = ssl.create_default_context()
            with socket.create_connection((host, port), timeout=timeout) as sock:
                with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                    cert = ssock.getpeercert()
                    proto = ssock.version() or "Unknown"
                    cipher_name, _, _ = ssock.cipher() or ("Unknown", None, None)
        except ssl.SSLCertVerificationError as exc:
            return SSLAnalysisResult(
                host=host, port=port, reachable=True,
                cert_subject="", cert_issuer="", not_before="", not_after="",
                days_until_expiry=0, protocol_version="", cipher_suite="",
                findings=[SSLFinding("Certificate Verification", "Critical",
                                      str(exc), "Fix the certificate chain or use a CA-signed cert.")],
                overall_grade="F", error=str(exc),
            )
        except Exception as exc:
            return SSLAnalysisResult(
                host=host, port=port, reachable=False,
                cert_subject="", cert_issuer="", not_before="", not_after="",
                days_until_expiry=0, protocol_version="", cipher_suite="",
                findings=[], overall_grade="F", error=str(exc),
            )

        # Parse cert fields
        subject = dict(x[0] for x in cert.get("subject", []))
        issuer = dict(x[0] for x in cert.get("issuer", []))
        not_before_str = cert.get("notBefore", "")
        not_after_str = cert.get("notAfter", "")

        try:
            not_after_dt = datetime.strptime(not_after_str, "%b %d %H:%M:%S %Y %Z")
            days_left = (not_after_dt - datetime.utcnow()).days
        except Exception:
            not_after_dt = datetime.utcnow()
            days_left = 0

        # ── Expiry checks ────────────────────────────────────────────────────
        if days_left <= 0:
            findings.append(SSLFinding("Certificate Expiry", "Critical",
                f"Certificate EXPIRED {abs(days_left)} day(s) ago",
                "Renew the certificate immediately — browsers will block all users."))
        elif days_left <= 14:
            findings.append(SSLFinding("Certificate Expiry", "High",
                f"Expires in {days_left} day(s)",
                "Renew within 24 hours to avoid service disruption."))
        elif days_left <= 30:
            findings.append(SSLFinding("Certificate Expiry", "Medium",
                f"Expires in {days_left} day(s)",
                "Plan certificate renewal this week."))
        else:
            findings.append(SSLFinding("Certificate Expiry", "OK",
                f"Valid for {days_left} more day(s)", ""))

        # ── Protocol version ─────────────────────────────────────────────────
        if proto in self.DEPRECATED_PROTOCOLS:
            findings.append(SSLFinding("TLS Protocol Version", "Critical",
                f"Negotiated deprecated protocol: {proto}",
                "Disable TLS 1.0 and 1.1; require TLS 1.2 minimum, prefer TLS 1.3."))
        elif proto == "TLSv1.2":
            findings.append(SSLFinding("TLS Protocol Version", "Low",
                "TLS 1.2 — acceptable but TLS 1.3 preferred",
                "Enable TLS 1.3 for improved security and performance."))
        else:
            findings.append(SSLFinding("TLS Protocol Version", "OK", f"{proto}", ""))

        # ── Cipher suite ─────────────────────────────────────────────────────
        weak = [w for w in self.WEAK_CIPHERS if w in cipher_name.upper()]
        if weak:
            findings.append(SSLFinding("Cipher Suite", "High",
                f"Weak cipher detected: {cipher_name}",
                "Disable RC4, DES, 3DES, EXPORT, and NULL ciphers. "
                "Prefer AES-256-GCM or CHACHA20-POLY1305."))
        else:
            findings.append(SSLFinding("Cipher Suite", "OK", cipher_name, ""))

        # ── Self-signed check ─────────────────────────────────────────────────
        if subject == issuer:
            findings.append(SSLFinding("Certificate Trust", "High",
                "Self-signed certificate detected",
                "Use a certificate from a trusted CA (e.g. Let's Encrypt) for public-facing services."))

        # ── SAN check ────────────────────────────────────────────────────────
        sans = cert.get("subjectAltName", [])
        if not sans:
            findings.append(SSLFinding("Subject Alt Names", "Medium",
                "No SAN entries found",
                "Modern browsers require SAN entries. Add SANs for all intended hostnames."))

        sev_order = {"Critical": 5, "High": 4, "Medium": 3, "Low": 2, "OK": 0}
        max_sev = max((sev_order.get(f.severity, 0) for f in findings), default=0)
        grade_map = {5: "F", 4: "D", 3: "C", 2: "B", 0: "A"}
        grade = grade_map.get(max_sev, "A")

        return SSLAnalysisResult(
            host=host, port=port, reachable=True,
            cert_subject=subject.get("commonName", str(subject)),
            cert_issuer=issuer.get("organizationName", str(issuer)),
            not_before=not_before_str, not_after=not_after_str,
            days_until_expiry=days_left, protocol_version=proto,
            cipher_suite=cipher_name, findings=findings, overall_grade=grade,
        )


# ==============================================================================
# ==============================================================================
#  MODULE: LIVE VULNERABILITY FEED (OSV.dev)
#  Closes the comparison-table gap: MOCK_CVE_DATABASE is 29 hardcoded
#  examples; this queries a real, continuously-updated aggregated feed —
#  the same category of source (GitHub Security Advisories, PyPA, npm
#  advisories, RustSec, Go vuln DB, etc.) that GitHub/Snyk draw from.
#  No API key needed, which is what makes it usable here without asking
#  the person running this app for a credential they may not have.
# ==============================================================================
# ==============================================================================

class OSVFeedClient:
    """
    Live package-vulnerability lookups against OSV.dev's public API.

    AUTHORSHIP NOTE (read before trusting this in production): this class
    was written against OSV's documented request/response schema and unit
    -tested against synthetic payloads shaped like that schema, but this
    was built in a sandboxed environment with no network egress, so the
    live HTTP call itself was never exercised against the real endpoint.
    The request/response shapes below match OSV's published API docs
    (https://ossf.github.io/osv-schema/, https://google.github.io/osv.dev/)
    as of this writing — verify the first real batch query by hand
    (`curl -X POST https://api.osv.dev/v1/querybatch -d '...'`) before
    relying on this for anything.

    Deliberately scoped to ecosystems OSV can resolve by name+version
    alone (PyPI, npm) — Docker base images aren't included because
    resolving OS-level packages inside an image requires actually
    enumerating that image's package list, which this SBOM generator
    doesn't do (it only reads the FROM line).
    """
    BATCH_URL = "https://api.osv.dev/v1/querybatch"
    ECOSYSTEM_MAP = {"python": "PyPI", "npm": "npm"}

    def __init__(self, timeout: float = 6.0):
        self.timeout = timeout
        self.last_error: Optional[str] = None
        self._cache: Dict[Tuple[str, str, str], List[Dict[str, str]]] = {}

    @staticmethod
    def _clean_version(version: str) -> Optional[str]:
        """None means 'query the package with no version pin' (OSV
        supports this — it returns everything known against that
        package), which is the honest thing to do for a range like
        '^4.17.21' or '>=1.2.0 <2.0.0' that this SBOM generator doesn't
        resolve to one concrete version. Sending the raw range string as
        if it were a pinned version would just silently match nothing.
        Strips common range-operator prefixes itself rather than trusting
        the caller to have already done it — SBOMGenerator's own parsers
        happen to lstrip these too, but this method has to be correct on
        its own for any future caller that doesn't."""
        v = (version or "").strip()
        if not v or v.lower() in ("unspecified", "latest"):
            return None
        v = v.lstrip("^~>=<")
        if any(ch in v for ch in " <>|*") or v.lower() in ("x", "x.x", "x.x.x"):
            return None
        return v or None

    def query_many(self, components: List[Tuple[str, str, str]]
                    ) -> Dict[str, List[Dict[str, str]]]:
        """
        components: (name, version, package_type) tuples.
        Returns {"name|version": [{"cve_id", "severity", "summary"}, ...]}.
        A KEY BEING PRESENT (even with an empty list) means that exact
        component was successfully checked live — distinct from being
        absent, which means it was never queried at all. That distinction
        matters: "checked live, zero known vulns" and "we have no data on
        this" are different claims and callers need to tell them apart.
        On any request-level failure this returns {} and sets
        self.last_error; callers should read that as "OSV was
        unreachable, fall back to the demo feed" — NOT as "zero
        vulnerabilities everywhere."
        """
        self.last_error = None
        queryable = [(n, v, t) for n, v, t in components if t in self.ECOSYSTEM_MAP]
        if not queryable:
            return {}

        out: Dict[str, List[Dict[str, str]]] = {}
        to_fetch: List[Tuple[str, str, str]] = []
        for name, version, ptype in queryable:
            key = (self.ECOSYSTEM_MAP[ptype], name, version)
            if key in self._cache:
                out[f"{name}|{version}"] = self._cache[key]
            else:
                to_fetch.append((name, version, ptype))
        if not to_fetch:
            return out

        queries = []
        for name, version, ptype in to_fetch:
            q: Dict[str, Any] = {"package": {"name": name, "ecosystem": self.ECOSYSTEM_MAP[ptype]}}
            clean_v = self._clean_version(version)
            if clean_v:
                q["version"] = clean_v
            queries.append(q)

        try:
            resp = requests.post(self.BATCH_URL, json={"queries": queries}, timeout=self.timeout)
            resp.raise_for_status()
            raw_results = resp.json().get("results", [])
        except Exception as e:
            self.last_error = f"OSV.dev query failed, falling back to demo CVE data: {e}"
            return out  # still return whatever the cache already had

        for (name, version, ptype), result in zip(to_fetch, raw_results):
            entries = [self._to_entry(v) for v in result.get("vulns", [])]
            key = (self.ECOSYSTEM_MAP[ptype], name, version)
            self._cache[key] = entries
            out[f"{name}|{version}"] = entries
        return out

    @staticmethod
    def _to_entry(vuln: Dict[str, Any]) -> Dict[str, str]:
        cve_id = next((a for a in vuln.get("aliases", []) if a.startswith("CVE-")), vuln.get("id", "?"))
        # OSV doesn't normalize severity to one score itself — a source
        # that supplies a plain label (common for GHSA-derived entries)
        # is used directly; a raw CVSS vector is flagged rather than
        # hand-parsed into a bucket this class isn't confident about.
        label = (vuln.get("database_specific") or {}).get("severity")
        if label:
            severity = str(label).title()
        elif vuln.get("severity"):
            severity = "See CVE"
        else:
            severity = "Unrated"
        return {"cve_id": cve_id, "severity": severity, "summary": (vuln.get("summary") or "")[:200]}


# ==============================================================================
# ==============================================================================
#  MODULE: SBOM GENERATOR (Software Bill of Materials)
#  Parses dependency manifests from any project and cross-references against
#  the local CVE feed. Outputs CycloneDX-inspired JSON.
# ==============================================================================
# ==============================================================================

@dataclass
class SBOMComponent:
    name: str
    version: str
    package_type: str   # "python" | "npm" | "docker-base" | "system"
    source_file: str
    known_cves: List[str]
    highest_severity: str
    cve_source: str = "demo"  # "demo" (MOCK_CVE_DATABASE) or "osv.dev" (live, checked this run)

@dataclass
class SBOMReport:
    project_name: str
    generated_at: str
    total_components: int
    vulnerable_count: int
    components: List[SBOMComponent]
    overall_risk: str
    parse_errors: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "bomFormat": "SentinelAI-SBOM",
            "specVersion": "1.0",
            "project": self.project_name,
            "generatedAt": self.generated_at,
            "summary": {
                "totalComponents": self.total_components,
                "vulnerableComponents": self.vulnerable_count,
                "overallRisk": self.overall_risk,
            },
            "components": [
                {
                    "name": c.name, "version": c.version,
                    "type": c.package_type, "sourceFile": c.source_file,
                    "knownCVEs": c.known_cves, "highestSeverity": c.highest_severity,
                    "cveSource": c.cve_source,
                }
                for c in self.components
            ],
            "parseErrors": self.parse_errors,
        }


class SBOMGenerator:
    """
    Parses requirements.txt, package.json, Pipfile, pyproject.toml,
    and Dockerfile FROM lines to build a component inventory, then
    cross-references each component against the local CVE feed.
    Outputs a CycloneDX-inspired SBOM in JSON.
    """

    def __init__(self, cve_feed: Optional[List[Dict[str, str]]] = None,
                 osv_client: Optional[OSVFeedClient] = None):
        self.cve_feed = cve_feed or MOCK_CVE_DATABASE
        self.parse_errors: List[str] = []
        # None (default) = demo-data-only, unchanged from before. Pass a
        # real OSVFeedClient to check live data for python/npm components;
        # anything OSV doesn't cover for, or that OSV fails to reach,
        # keeps its demo-feed result rather than losing data entirely.
        self.osv_client = osv_client

    def _cves_for(self, name: str) -> Tuple[List[str], str]:
        cves: List[str] = []
        highest = "None"
        sev_order = {"Critical": 4, "High": 3, "Medium": 2, "Low": 1, "None": 0}
        for entry in self.cve_feed:
            if entry["package"].lower() == name.lower():
                cves.append(entry["cve_id"])
                if sev_order.get(entry["severity"], 0) > sev_order.get(highest, 0):
                    highest = entry["severity"]
        return cves, highest

    def _parse_requirements(self, content: str, source_file: str) -> List[SBOMComponent]:
        components: List[SBOMComponent] = []
        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            for sep in ["==", ">=", "<=", "~=", "!="]:
                if sep in line:
                    name, _, version = line.partition(sep)
                    cves, highest = self._cves_for(name.strip())
                    components.append(SBOMComponent(
                        name=name.strip(), version=version.strip().split(",")[0],
                        package_type="python", source_file=source_file,
                        known_cves=cves, highest_severity=highest,
                    ))
                    break
            else:
                cves, highest = self._cves_for(line)
                components.append(SBOMComponent(
                    name=line, version="unspecified", package_type="python",
                    source_file=source_file, known_cves=cves, highest_severity=highest,
                ))
        return components

    def _parse_package_json(self, content: str, source_file: str) -> List[SBOMComponent]:
        components: List[SBOMComponent] = []
        try:
            data = json.loads(content)
            for section in ("dependencies", "devDependencies"):
                for name, version in data.get(section, {}).items():
                    cves, highest = self._cves_for(name)
                    components.append(SBOMComponent(
                        name=name, version=str(version).lstrip("^~>="),
                        package_type="npm", source_file=source_file,
                        known_cves=cves, highest_severity=highest,
                    ))
        except Exception as e:
            # Previously silent: an unparseable package.json (bad JSON,
            # JSONC comments, a truncated upload) produced an empty
            # component list with NO indication anything went wrong — a
            # user would see "0 npm components" and reasonably read that
            # as "no JS dependencies" rather than "we failed to read this
            # file." Now the caller (generate()) surfaces this instead.
            self.parse_errors.append(f"{source_file}: could not parse as JSON ({e})")
        return components

    def _parse_dockerfile(self, content: str, source_file: str) -> List[SBOMComponent]:
        components: List[SBOMComponent] = []
        for line in content.splitlines():
            line = line.strip()
            if line.upper().startswith("FROM "):
                parts = line.split()
                if len(parts) >= 2:
                    image = parts[1]
                    name, _, tag = image.partition(":")
                    cves, highest = self._cves_for(name)
                    components.append(SBOMComponent(
                        name=name, version=tag or "latest", package_type="docker-base",
                        source_file=source_file, known_cves=cves, highest_severity=highest,
                    ))
        return components

    def generate(self, files: Dict[str, str], project_name: str = "Project") -> SBOMReport:
        self.parse_errors = []  # reset per-run; this instance persists across reruns in session_state
        all_components: List[SBOMComponent] = []
        for file_name, content in files.items():
            base = file_name.replace("\\", "/").split("/")[-1].lower()
            if base in ("requirements.txt", "requirements-dev.txt", "requirements-prod.txt"):
                all_components.extend(self._parse_requirements(content, file_name))
            elif base == "package.json":
                all_components.extend(self._parse_package_json(content, file_name))
            elif base == "dockerfile":
                all_components.extend(self._parse_dockerfile(content, file_name))
            elif base == "pipfile":
                all_components.extend(self._parse_requirements(content, file_name))

        if self.osv_client is not None and all_components:
            sev_order = {"Critical": 4, "High": 3, "Medium": 2, "Low": 1,
                         "See CVE": 1, "Unrated": 0, "None": 0}
            live = self.osv_client.query_many(
                [(c.name, c.version, c.package_type) for c in all_components]
            )
            if self.osv_client.last_error:
                self.parse_errors.append(self.osv_client.last_error)
            for c in all_components:
                key = f"{c.name}|{c.version}"
                if key not in live:
                    continue  # not queryable, or the batch call failed — demo data stands
                entries = live[key]
                c.known_cves = [e["cve_id"] for e in entries]
                c.cve_source = "osv.dev"
                highest = "None"
                for e in entries:
                    if sev_order.get(e["severity"], 0) > sev_order.get(highest, 0):
                        highest = e["severity"]
                c.highest_severity = highest if entries else "None"

        vulnerable = [c for c in all_components if c.known_cves]
        sev_order = {"Critical": 4, "High": 3, "Medium": 2, "Low": 1, "None": 0}
        max_sev = max((sev_order.get(c.highest_severity, 0) for c in all_components), default=0)
        overall = {4: "Critical", 3: "High", 2: "Medium", 1: "Low", 0: "Clean"}.get(max_sev, "Clean")

        return SBOMReport(
            project_name=project_name,
            generated_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            total_components=len(all_components),
            vulnerable_count=len(vulnerable),
            components=all_components,
            overall_risk=overall,
            parse_errors=list(self.parse_errors),
        )


