@dataclass
class IoCMatch:
    ioc_type: str        # "ip" | "domain" | "hash" | "user_agent"
    ioc_value: str
    matched_in: str       # event_id or file reference
    confidence: str
    threat_family: str
    first_seen: str

@dataclass
class ThreatHuntResult:
    ioc_matches: List[IoCMatch]
    persistence_indicators: List[str]
    lateral_movement_indicators: List[str]
    beaconing_candidates: List[Dict[str, Any]]
    overall_threat_level: str
    hunted_at: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "ioc_matches": [
                {"type": m.ioc_type, "value": m.ioc_value, "matched_in": m.matched_in,
                 "confidence": m.confidence, "family": m.threat_family}
                for m in self.ioc_matches
            ],
            "persistence_indicators": self.persistence_indicators,
            "lateral_movement_indicators": self.lateral_movement_indicators,
            "beaconing_candidates": self.beaconing_candidates,
            "overall_threat_level": self.overall_threat_level,
            "hunted_at": self.hunted_at,
        }


# Small curated IoC feed — in production this would sync from a live threat
# intel source (MISP, AlienVault OTX, etc.). Kept local/static here since
# this sandbox has no persistent network access to a live feed.
KNOWN_MALICIOUS_IOCS: Dict[str, Dict[str, str]] = {
    "185.220.101.5":  {"type": "ip", "family": "TOR Exit Node", "confidence": "Medium"},
    "45.33.21.90":    {"type": "ip", "family": "Known Scanner Infrastructure", "confidence": "Medium"},
    "89.248.167.131": {"type": "ip", "family": "Known Botnet C2", "confidence": "High"},
    "194.26.29.156":  {"type": "ip", "family": "Known Malicious Range", "confidence": "Medium"},
    "91.240.118.172": {"type": "ip", "family": "Known Malicious Range", "confidence": "Medium"},
}

SUSPICIOUS_USER_AGENTS: List[str] = [
    "sqlmap", "nikto", "nmap", "masscan", "curl/7", "python-requests",
    "gobuster", "wpscan", "dirbuster", "hydra", "metasploit",
]


class ThreatHunter:
    """
    Correlates network telemetry against a curated IoC feed, detects
    persistence/lateral-movement patterns in log payloads, and identifies
    beaconing candidates (regular time-interval connections to the same
    destination — a classic C2 communication signature).
    """

    def __init__(self, ioc_feed: Optional[Dict[str, Dict[str, str]]] = None):
        self.ioc_feed = ioc_feed or KNOWN_MALICIOUS_IOCS

    def _match_iocs(self, events: List[Any]) -> List[IoCMatch]:
        matches: List[IoCMatch] = []
        for event in events:
            ip = getattr(event, "source_ip", "")
            if ip in self.ioc_feed:
                info = self.ioc_feed[ip]
                matches.append(IoCMatch(
                    ioc_type=info["type"], ioc_value=ip,
                    matched_in=getattr(event, "event_id", "?"),
                    confidence=info["confidence"], threat_family=info["family"],
                    first_seen=datetime.fromtimestamp(getattr(event, "timestamp", time.time())).strftime("%Y-%m-%d %H:%M:%S"),
                ))
            payload = getattr(event, "raw_payload", "").lower()
            for ua in SUSPICIOUS_USER_AGENTS:
                if ua in payload:
                    matches.append(IoCMatch(
                        ioc_type="user_agent", ioc_value=ua,
                        matched_in=getattr(event, "event_id", "?"),
                        confidence="High", threat_family="Reconnaissance/Attack Tooling",
                        first_seen=datetime.fromtimestamp(getattr(event, "timestamp", time.time())).strftime("%Y-%m-%d %H:%M:%S"),
                    ))
        return matches

    def _detect_persistence(self, malware_findings: List[MalwareFinding]) -> List[str]:
        indicators = []
        for f in malware_findings:
            if f.category in ("Backdoor",):
                indicators.append(f"{f.pattern_name} in {f.file_name}:{f.line_number}")
        return indicators

    def _detect_lateral_movement(self, events: List[Any]) -> List[str]:
        indicators = []
        internal_targets: Dict[str, Set[str]] = {}
        for event in events:
            ip = getattr(event, "source_ip", "")
            asset = getattr(event, "target_asset", "")
            if ip and asset:
                internal_targets.setdefault(ip, set()).add(asset)
        for ip, assets in internal_targets.items():
            if len(assets) >= 3:
                indicators.append(
                    f"Source {ip} accessed {len(assets)} distinct internal assets "
                    f"({', '.join(sorted(assets))}) — possible lateral movement/reconnaissance."
                )
        return indicators

    def _detect_beaconing(self, events: List[Any]) -> List[Dict[str, Any]]:
        """Groups events by source IP + target and looks for near-regular time intervals."""
        by_pair: Dict[Tuple[str, str], List[float]] = {}
        for event in events:
            key = (getattr(event, "source_ip", ""), getattr(event, "target_asset", ""))
            by_pair.setdefault(key, []).append(getattr(event, "timestamp", 0.0))

        candidates = []
        for (ip, asset), timestamps in by_pair.items():
            if len(timestamps) < 3:
                continue
            timestamps.sort()
            intervals = [timestamps[i+1] - timestamps[i] for i in range(len(timestamps) - 1)]
            if not intervals:
                continue
            avg_interval = sum(intervals) / len(intervals)
            variance = sum((iv - avg_interval) ** 2 for iv in intervals) / len(intervals)
            std_dev = variance ** 0.5
            # Low variance relative to mean = regular interval = possible beaconing
            if avg_interval > 0 and (std_dev / avg_interval) < 0.15 and len(timestamps) >= 3:
                candidates.append({
                    "source_ip": ip, "target": asset,
                    "connection_count": len(timestamps),
                    "avg_interval_seconds": round(avg_interval, 1),
                    "regularity": "High" if (std_dev / avg_interval) < 0.05 else "Medium",
                })
        return candidates

    def hunt(self, events: List[Any], malware_findings: List[MalwareFinding]) -> ThreatHuntResult:
        ioc_matches = self._match_iocs(events)
        persistence = self._detect_persistence(malware_findings)
        lateral = self._detect_lateral_movement(events)
        beaconing = self._detect_beaconing(events)

        high_conf_iocs = sum(1 for m in ioc_matches if m.confidence == "High")
        if high_conf_iocs > 0 or persistence:
            level = "Critical"
        elif ioc_matches or lateral or beaconing:
            level = "High"
        elif events:
            level = "Low"
        else:
            level = "None"

        return ThreatHuntResult(
            ioc_matches=ioc_matches, persistence_indicators=persistence,
            lateral_movement_indicators=lateral, beaconing_candidates=beaconing,
            overall_threat_level=level, hunted_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        )


# ==============================================================================
# ==============================================================================
#  AGENT SWARM MODULE PACK — PDF Threat Analyzer, Authorization/Scope Manager,
#  and the Swarm Orchestrator (bounded worker pool + input-scaled task queue,
#  with authorization enforced in code, not just UI copy)
# ==============================================================================
# ==============================================================================
# ==============================================================================
# ==============================================================================
#  MODULE: PDF THREAT ANALYZER
#  Byte-level structural analysis of PDF files for known malware indicators.
#  No external PDF library required — pure byte-pattern scanning, which also
#  means it never actually parses/renders/executes anything in the PDF.
# ==============================================================================
# ==============================================================================

@dataclass
class PDFIndicator:
    indicator: str
    severity: str
    count: int
    explanation: str

    def to_dict(self) -> Dict[str, Any]:
        return {"indicator": self.indicator, "severity": self.severity,
                "count": self.count, "explanation": self.explanation}

@dataclass
class PDFAnalysisResult:
    file_name: str
    file_size: int
    indicators: List[PDFIndicator]
    risk_level: str
    is_encrypted: bool

    def to_dict(self) -> Dict[str, Any]:
        return {
            "file_name": self.file_name, "file_size_bytes": self.file_size,
            "risk_level": self.risk_level, "is_encrypted": self.is_encrypted,
            "indicators": [i.to_dict() for i in self.indicators],
        }


PDF_SUSPICIOUS_KEYS: List[Dict[str, Any]] = [
    {"key": b"/JavaScript", "name": "Embedded JavaScript", "severity": "High",
     "explanation": "PDFs can execute JavaScript on open — a common exploit and phishing vector."},
    {"key": b"/JS", "name": "JS action shorthand", "severity": "High",
     "explanation": "Shorthand JavaScript action key — same risk class as /JavaScript."},
    {"key": b"/OpenAction", "name": "Auto-execute action on open", "severity": "High",
     "explanation": "Triggers an action automatically when the PDF is opened — commonly abused "
                    "to launch JavaScript or external content without user interaction."},
    {"key": b"/AA", "name": "Additional Actions (event-triggered)", "severity": "Medium",
     "explanation": "Executes actions on events like page-open or form-field changes — can hide "
                    "malicious triggers behind innocuous-looking form interactions."},
    {"key": b"/Launch", "name": "Launch external application", "severity": "Critical",
     "explanation": "Can launch an external program or command directly from the PDF — a severe "
                    "code-execution-adjacent risk."},
    {"key": b"/EmbeddedFile", "name": "Embedded file", "severity": "Medium",
     "explanation": "PDFs can embed arbitrary files inside themselves, sometimes used to smuggle "
                    "malware payloads past perimeter scanners."},
    {"key": b"/RichMedia", "name": "Embedded rich media (Flash/3D)", "severity": "Medium",
     "explanation": "Legacy rich-media content has a long history of exploited parser vulnerabilities."},
    {"key": b"/XFA", "name": "XFA dynamic XML form", "severity": "Low",
     "explanation": "Adobe XFA forms have had multiple parser-level CVEs over the years."},
    {"key": b"/SubmitForm", "name": "Auto form submission action", "severity": "Medium",
     "explanation": "Can silently submit form data to a remote URL — a data-exfiltration vector."},
    {"key": b"/ObjStm", "name": "Compressed object streams", "severity": "Low",
     "explanation": "Object streams can hide document structure from naive text-based scanners. "
                    "Not inherently malicious, but worth noting for deeper manual review."},
    {"key": b"/Encrypt", "name": "Encrypted PDF", "severity": "Medium",
     "explanation": "Encrypted PDFs can evade some AV/content scanners. Verify the source is trusted."},
]


class PDFThreatAnalyzer:
    """
    Scans raw PDF bytes for known malware-indicative structural elements
    (embedded JS, auto-launch actions, embedded files, etc.) without ever
    parsing or rendering the PDF — pure byte-pattern counting. This makes it
    safe to run on completely untrusted PDF files: nothing in the file is
    ever executed or interpreted.
    """

    def analyze(self, file_name: str, raw_bytes: bytes) -> PDFAnalysisResult:
        indicators: List[PDFIndicator] = []
        for rule in PDF_SUSPICIOUS_KEYS:
            count = raw_bytes.count(rule["key"])
            if count > 0:
                indicators.append(PDFIndicator(
                    indicator=rule["name"], severity=rule["severity"],
                    count=count, explanation=rule["explanation"],
                ))

        is_encrypted = b"/Encrypt" in raw_bytes
        sev_order = {"Critical": 4, "High": 3, "Medium": 2, "Low": 1}
        max_sev = max((sev_order.get(i.severity, 0) for i in indicators), default=0)
        risk = {4: "Critical", 3: "High", 2: "Medium", 1: "Low", 0: "Clean"}.get(max_sev, "Clean")

        return PDFAnalysisResult(
            file_name=file_name, file_size=len(raw_bytes),
            indicators=indicators, risk_level=risk, is_encrypted=is_encrypted,
        )


# ==============================================================================
# ==============================================================================
#  MODULE: AUTHORIZATION & SCOPE MANAGER
#  Enforces an explicit, per-target consent ledger. This is not a UI warning —
#  the Swarm Orchestrator itself refuses to execute any URL/host task unless
#  the target matches an entry the user explicitly confirmed here first.
# ==============================================================================
# ==============================================================================

@dataclass
class ScopeEntry:
    scope_id: str
    target_type: str    # "domain" | "ip" | "directory"
    value: str
    authorized_at: str

    def to_dict(self) -> Dict[str, Any]:
        return {"scope_id": self.scope_id, "type": self.target_type,
                "value": self.value, "authorized_at": self.authorized_at}


class AuthorizationManager:
    """
    A simple, explicit scope ledger. Nothing is 'authorized' by default —
    the user must actively add each domain, IP, or directory here (with an
    explicit confirmation) before the Swarm Orchestrator will run any task
    against it. This mirrors how real authorized penetration-testing
    engagements define scope in writing before any testing begins.
    """

    def __init__(self) -> None:
        self._scope: Dict[str, ScopeEntry] = {}

    def add_scope(self, target_type: str, value: str, confirmed: bool) -> ScopeEntry:
        if not confirmed:
            raise PermissionError(
                "Explicit authorization confirmation is required before adding a scan target."
            )
        value = value.strip().lower() if target_type != "directory" else value.strip()
        scope_id = hashlib.sha256(f"{target_type}:{value}".encode()).hexdigest()[:10]
        entry = ScopeEntry(
            scope_id=scope_id, target_type=target_type, value=value,
            authorized_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        )
        self._scope[scope_id] = entry
        return entry

    def is_authorized(self, target_type: str, value: str) -> bool:
        value_norm = value.strip().lower() if target_type != "directory" else value.strip()
        for entry in self._scope.values():
            if entry.target_type != target_type:
                continue
            if target_type == "directory":
                try:
                    base = os.path.abspath(entry.value)
                    target = os.path.abspath(value_norm)
                    common = os.path.commonpath([base, target])
                    if common == base:
                        return True
                except Exception:
                    continue
            elif target_type == "domain":
                if value_norm == entry.value or value_norm.endswith("." + entry.value):
                    return True
            elif target_type == "ip":
                if value_norm == entry.value:
                    return True
        return False

    def list_scope(self) -> List[ScopeEntry]:
        return list(self._scope.values())

    def remove_scope(self, scope_id: str) -> None:
        self._scope.pop(scope_id, None)

    def clear(self) -> None:
        self._scope.clear()


# ==============================================================================
# ==============================================================================
#  MODULE: SWARM ORCHESTRATOR
#  Fans a large task queue (one per file / URL / host) out across a
#  worker pool with a hard-capped size — this is the technically honest
#  version of "send many agents": task count scales with input size,
#  worker concurrency is capped for machine safety, and every URL/host
#  task is gated through AuthorizationManager before it can run.
# ==============================================================================
# ==============================================================================

class AgentTaskStatus(str, Enum):
    PENDING  = "Pending"
    RUNNING  = "Running"
    DONE     = "Done"
    FAILED   = "Failed"
    REJECTED = "Rejected (not in authorized scope)"
    SKIPPED  = "Skipped (unchanged since last scan)"


@dataclass
class AgentTask:
    task_id: str
    task_type: str     # "file_scan" | "file_scan_inmem" | "url_audit" | "host_audit" | "pdf_scan"
                       # | "container_scan" | "dependency_scan" | "pattern_scan"
    target: str
    status: AgentTaskStatus = AgentTaskStatus.PENDING
    result_summary: str = ""
    findings_count: int = 0
    critical_count: int = 0
    error: str = ""
    started_at: str = ""
    completed_at: str = ""
    raw_results: Any = None
    retry_count: int = 0

    def to_dict(self) -> Dict[str, Any]:
        return {
            "task_id": self.task_id, "type": self.task_type, "target": self.target,
            "status": self.status.value if isinstance(self.status, AgentTaskStatus) else self.status,
            "summary": self.result_summary, "findings": self.findings_count,
            "critical": self.critical_count, "error": self.error,
            "started": self.started_at, "completed": self.completed_at,
            "retries": self.retry_count,
        }


@dataclass
class SwarmIntelligenceBriefing:
    """The automatic post-run synthesis: every swarm run now feeds its own
    results into the Exploit Chain Correlator, Posture Scorer, and Executive
    Summary generator, so the result of a swarm run is one consolidated
    picture rather than a pile of unconnected task results."""
    exploit_chains: List["ExploitChain"]
    posture_score: "PostureScore"
    executive_summary: str
    generated_at: str
    # Optional: populated only when synthesize() is given an
    # AutoResponseEngine — see synthesize()'s docstring for why this is
    # still bounded by that engine's existing circuit breaker rather than
    # a new, less-supervised path.
    auto_response_events: List[Any] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "exploit_chains": [c.to_dict() for c in self.exploit_chains],
            "posture_score": self.posture_score.to_dict(),
            "executive_summary": self.executive_summary,
            "generated_at": self.generated_at,
            "auto_response_events": [e.to_dict() for e in self.auto_response_events],
        }


@dataclass
class SwarmReport:
    total_tasks: int
    completed: int
    failed: int
    rejected: int
    skipped: int
    total_findings: int
    total_critical: int
    tasks: List[AgentTask]
    generated_at: str
    duration_seconds: float = 0.0
    briefing: Optional[SwarmIntelligenceBriefing] = None
    # Findings from SemanticVulnerabilityScanner.analyze_project() — real
    # vulnerabilities that only appear when tracing taint ACROSS files
    # (see analyze_project's docstring), which don't belong to any single
    # task's raw_results the way per-file findings do.
    cross_file_findings: List[Any] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        d = {
            "total_tasks": self.total_tasks, "completed": self.completed,
            "failed": self.failed, "rejected": self.rejected, "skipped": self.skipped,
            "total_findings": self.total_findings, "total_critical": self.total_critical,
            "generated_at": self.generated_at, "duration_seconds": round(self.duration_seconds, 2),
            "tasks": [t.to_dict() for t in self.tasks],
            "cross_file_findings_count": len(self.cross_file_findings),
        }
        if self.briefing:
            d["intelligence_briefing"] = self.briefing.to_dict()
        return d


class SwarmOrchestrator:
    """
    Builds a task queue (scales with input — one task per file/URL/host,
    however many that is) and executes it across a bounded worker pool.

    Safety properties, enforced in code (not just documented):
      - max_workers is hard-clamped to a safe range (1-64). No amount of
        input size increases concurrent execution beyond this; it only
        increases queue depth, which is the correct way to scale this
        kind of work on a single machine.
      - Every url_audit / host_audit task is checked against
        AuthorizationManager.is_authorized() BEFORE execution. Tasks
        outside the authorized scope are marked REJECTED and never run —
        this is enforced here, not just in the UI.
      - file_scan / file_scan_inmem / pdf_scan tasks operate only on files
        the user directly uploaded or explicitly authorized a local
        directory for; there is no code path that fetches arbitrary
        remote files.
    """

    HARD_MAX_WORKERS = 64
    MAX_RETRIES = 2
    FAILURE_RATE_BACKOFF_THRESHOLD = 0.3
    CLEAN_BATCHES_BEFORE_RAMP_UP = 2

    _CONTAINER_FILENAMES: Set[str] = {"dockerfile", "docker-compose.yml", "docker-compose.yaml",
                                       "compose.yml", "compose.yaml"}
    _DEPENDENCY_FILENAMES: Set[str] = {"requirements.txt", "requirements-dev.txt", "requirements-prod.txt",
                                        "package.json", "pipfile"}
    _PATTERN_LANG_EXTENSIONS: Dict[str, str] = {
        ".js": "javascript", ".ts": "javascript", ".jsx": "javascript", ".tsx": "javascript",
        ".php": "php", ".java": "java", ".go": "go", ".c": "c", ".h": "c", ".cpp": "c",
        ".cs": "csharp", ".rb": "ruby", ".rs": "rust", ".kt": "kotlin", ".kts": "kotlin",
        ".swift": "swift", ".scala": "scala", ".sc": "scala",  # added: extended_rules.py batch 1
        ".pl": "perl", ".pm": "perl", ".m": "objc", ".mm": "objc",  # added: batch 6
        ".ex": "elixir", ".exs": "elixir", ".lua": "lua", ".dart": "dart", ".ps1": "powershell",
    }

    def __init__(self, auth_manager: AuthorizationManager, max_workers: int = 16):
        self.auth = auth_manager
        self.max_workers = max(1, min(int(max_workers), self.HARD_MAX_WORKERS))
        self.tasks: List[AgentTask] = []
        self._lock = threading.Lock()
        self._file_hash_cache: Dict[str, str] = {}
        self._collected_entry_points: List["EntryPoint"] = []
        self.effective_worker_history: List[int] = []  # telemetry: concurrency over the run, for introspection/testing
        # Content read directly from disk during build_directory_tasks().
        # Every task type detect_task_type() can produce (file_scan_inmem,
        # pattern_scan, container_scan, dependency_scan, pdf_scan — note
        # "file_scan" itself is never produced by anything) reads its
        # content EXCLUSIVELY from a file_contents dict keyed by path; a
        # directory-scanned file was never uploaded, so it can't be in the
        # caller-supplied file_contents. Without capturing it here, every
        # directory scan would silently execute every task against an
        # empty string — no error, no crash, zero findings, every time.
        self._directory_file_contents: Dict[str, Any] = {}

    def reset(self) -> None:
        self.tasks = []
        self._collected_entry_points = []
        self._directory_file_contents = {}

    def clear_incremental_cache(self) -> None:
        self._file_hash_cache = {}

    def _next_id(self) -> str:
        return f"task_{len(self.tasks) + 1:06d}"

    @classmethod
    def detect_task_type(cls, filename: str) -> str:
        """Routes a file to the RIGHT engine based on its name/extension —
        this is what makes the swarm multi-engine rather than Python-only."""
        base = filename.replace("\\", "/").split("/")[-1].lower()
        if base in cls._CONTAINER_FILENAMES or base.startswith("dockerfile"):
            return "container_scan"
        if base in cls._DEPENDENCY_FILENAMES:
            return "dependency_scan"
        if base.endswith((".yml", ".yaml")):
            return "container_scan"  # ContainerSecurityAnalyzer itself no-ops if it's not a K8s manifest
        if base.endswith(".pdf"):
            return "pdf_scan"
        if base.endswith(".py"):
            return "file_scan_inmem"
        ext = "." + base.rsplit(".", 1)[-1] if "." in base else ""
        if ext in cls._PATTERN_LANG_EXTENSIONS:
            return "pattern_scan"
        return "file_scan_inmem"  # fallback: still gets code/malware/secrets scanning

    def build_directory_tasks(self, directory: str,
                              extensions: Optional[Tuple[str, ...]] = None) -> List[AgentTask]:
        if not self.auth.is_authorized("directory", directory):
            raise PermissionError(
                f"Directory '{directory}' is not in the authorized scope. "
                f"Add it in the Authorization panel first."
            )
        default_exts = (".py", ".js", ".ts", ".php", ".java", ".go", ".c", ".cs", ".rb", ".rs",
                        ".yml", ".yaml", ".pdf") + tuple(self._DEPENDENCY_FILENAMES)
        allowed = extensions or default_exts
        new_tasks: List[AgentTask] = []
        for root, dirs, files in os.walk(directory):
            # Prune vendored/generated/VCS directories at the source — the
            # same exclusion list the live watcher uses, so "scan this
            # directory" and "watch this directory" agree on what counts
            # as this project's own code rather than one of them silently
            # including node_modules/.git and the other not.
            dirs[:] = [d for d in dirs if d not in LIVE_WATCH_EXCLUDED_DIRS]
            for fn in files:
                fn_lower = fn.lower()
                if fn_lower.endswith(tuple(e for e in allowed if e.startswith("."))) or fn_lower in allowed \
                   or fn_lower in self._CONTAINER_FILENAMES or fn_lower in self._DEPENDENCY_FILENAMES:
                    path = os.path.join(root, fn)
                    content = self._read_disk_file(path, fn_lower)
                    if content is None:
                        continue  # unreadable, binary where text expected, or over the size cap — skip, don't crash the build
                    self._directory_file_contents[path] = content
                    task_type = self.detect_task_type(fn)
                    t = AgentTask(task_id=self._next_id(), task_type=task_type, target=path)
                    new_tasks.append(t)
                    self.tasks.append(t)
        return new_tasks

    def _read_disk_file(self, path: str, fn_lower: str) -> Optional[Any]:
        """Reads one file for a directory-based scan, matching the content
        type each downstream engine expects: raw bytes for PDFs (the PDF
        analyzer parses the binary structure directly), decoded text for
        everything else. Applies the same size cap as the live watcher so a
        stray multi-hundred-MB file in a scanned directory can't stall or
        blow up memory on a swarm run."""
        try:
            if os.path.getsize(path) > LIVE_WATCH_MAX_FILE_BYTES:
                return None
            with open(path, "rb") as fh:
                raw = fh.read()
        except OSError:
            return None
        if fn_lower.endswith(".pdf"):
            return raw
        if b"\x00" in raw[:8192]:
            return None  # binary file where text content is expected — nothing to scan
        return raw.decode("utf-8", errors="ignore")

    def build_file_tasks(self, file_names: List[str]) -> List[AgentTask]:
        """For files the user directly uploaded — inherently in scope since
        the user explicitly provided the bytes. Auto-routes by file type."""
        new_tasks = []
        for name in file_names:
            task_type = self.detect_task_type(name)
            t = AgentTask(task_id=self._next_id(), task_type=task_type, target=name)
            new_tasks.append(t)
            self.tasks.append(t)
        return new_tasks

    def build_pdf_tasks(self, file_names: List[str]) -> List[AgentTask]:
        new_tasks = []
        for name in file_names:
            t = AgentTask(task_id=self._next_id(), task_type="pdf_scan", target=name)
            new_tasks.append(t)
            self.tasks.append(t)
        return new_tasks

    def build_url_tasks(self, urls: List[str]) -> List[AgentTask]:
        import urllib.parse
        new_tasks = []
        for u in urls:
            host = urllib.parse.urlparse(u).hostname or u
            authorized = self.auth.is_authorized("domain", host)
            t = AgentTask(
                task_id=self._next_id(), task_type="url_audit", target=u,
                status=AgentTaskStatus.PENDING if authorized else AgentTaskStatus.REJECTED,
                error="" if authorized else f"Host '{host}' not in authorized scope.",
            )
            new_tasks.append(t)
            self.tasks.append(t)
        return new_tasks

    def build_host_tasks(self, hosts: List[str]) -> List[AgentTask]:
        new_tasks = []
        for h in hosts:
            h_clean = h.strip()
            authorized = self.auth.is_authorized("ip", h_clean) or self.auth.is_authorized("domain", h_clean)
            t = AgentTask(
                task_id=self._next_id(), task_type="host_audit", target=h_clean,
                status=AgentTaskStatus.PENDING if authorized else AgentTaskStatus.REJECTED,
                error="" if authorized else f"Host '{h_clean}' not in authorized scope.",
            )
            new_tasks.append(t)
            self.tasks.append(t)
        return new_tasks

    @staticmethod
    def _content_hash(content: Any) -> str:
        if isinstance(content, bytes):
            return hashlib.sha256(content).hexdigest()
        return hashlib.sha256(str(content).encode("utf-8", errors="ignore")).hexdigest()

    def _maybe_skip_unchanged(self, task: AgentTask, file_contents: Optional[Dict[str, Any]]) -> bool:
        """Incremental scanning: if this exact target's content hash matches
        the last time this orchestrator instance scanned it, skip re-running
        every engine on it. Returns True (and mutates task in place) if skipped."""
        content: Any = None
        if task.task_type == "file_scan":
            try:
                with open(task.target, "rb") as fh:
                    content = fh.read()
            except Exception:
                return False
        elif task.task_type in ("file_scan_inmem", "pdf_scan", "container_scan",
                                "dependency_scan", "pattern_scan"):
            content = (file_contents or {}).get(task.target)
        if content is None:
            return False

        digest = self._content_hash(content)
        if self._file_hash_cache.get(task.target) == digest:
            task.status = AgentTaskStatus.SKIPPED
            task.result_summary = "Unchanged since last scan — skipped"
            task.completed_at = datetime.now().strftime("%H:%M:%S")
            return True
        self._file_hash_cache[task.target] = digest
        return False

    def _execute_task(self, task: AgentTask, engines: Dict[str, Any],
                      file_contents: Optional[Dict[str, Any]] = None,
                      progress_cb: Optional[Any] = None) -> AgentTask:
        if task.status in (AgentTaskStatus.REJECTED, AgentTaskStatus.SKIPPED):
            if progress_cb:
                progress_cb()
            return task

        task.status = AgentTaskStatus.RUNNING
        task.started_at = task.started_at or datetime.now().strftime("%H:%M:%S")

        try:
            if task.task_type == "file_scan":
                with open(task.target, encoding="utf-8", errors="ignore") as fh:
                    content = fh.read()
                findings: List[Any] = []
                if task.target.endswith(".py"):
                    findings += engines["semantic"].analyze_python(task.target, content)
                    findings += scan_for_evasion(task.target, content)
                    if "surface" in engines:
                        self._collected_entry_points.extend(engines["surface"].analyze(task.target, content))
                findings += engines["code"].scan_text(task.target, content)
                findings += engines["malware"].scan(task.target, content)
                findings += engines["secrets"].scan(task.target, content)
                task.raw_results = findings
                task.findings_count = len(findings)
                task.critical_count = len([f for f in findings if getattr(f, "severity", "") == "Critical"])
                task.result_summary = f"{task.findings_count} finding(s), {task.critical_count} critical"

            elif task.task_type == "file_scan_inmem":
                content = (file_contents or {}).get(task.target, "")
                findings = []
                if task.target.endswith(".py"):
                    findings += engines["semantic"].analyze_python(task.target, content)
                    findings += scan_for_evasion(task.target, content)
                    if "surface" in engines:
                        self._collected_entry_points.extend(engines["surface"].analyze(task.target, content))
                findings += engines["code"].scan_text(task.target, content)
                findings += engines["malware"].scan(task.target, content)
                findings += engines["secrets"].scan(task.target, content)
                task.raw_results = findings
                task.findings_count = len(findings)
                task.critical_count = len([f for f in findings if getattr(f, "severity", "") == "Critical"])
                task.result_summary = f"{task.findings_count} finding(s), {task.critical_count} critical"

            elif task.task_type == "pattern_scan":
                content = (file_contents or {}).get(task.target, "")
                ext = "." + task.target.rsplit(".", 1)[-1].lower() if "." in task.target else ""
                language = self._PATTERN_LANG_EXTENSIONS.get(ext, "")
                findings = []
                findings += engines["pattern"].scan(task.target, content, language=language or None)
                findings += engines["code"].scan_text(task.target, content)
                findings += engines["malware"].scan(task.target, content)
                findings += engines["secrets"].scan(task.target, content)
                task.raw_results = findings
                task.findings_count = len(findings)
                task.critical_count = len([f for f in findings if getattr(f, "severity", "") == "Critical"])
                task.result_summary = f"{task.findings_count} finding(s) [{language or 'unknown'}], {task.critical_count} critical"

            elif task.task_type == "container_scan":
                content = (file_contents or {}).get(task.target, "")
                findings = engines["container"].analyze(task.target, content)
                task.raw_results = findings
                task.findings_count = len(findings)
                task.critical_count = len([f for f in findings if f.severity == "Critical"])
                task.result_summary = f"{task.findings_count} finding(s), {task.critical_count} critical"

            elif task.task_type == "dependency_scan":
                content = (file_contents or {}).get(task.target, "")
                findings = engines["dependency"].scan_manifest(content)
                task.raw_results = findings
                task.findings_count = len(findings)
                task.critical_count = len([f for f in findings if f.severity == "Critical"])
                task.result_summary = f"{task.findings_count} known-vulnerable dependenc{'y' if task.findings_count==1 else 'ies'}"

            elif task.task_type == "pdf_scan":
                raw_bytes = (file_contents or {}).get(task.target, b"")
                result = engines["pdf"].analyze(task.target, raw_bytes)
                task.raw_results = result
                task.findings_count = len(result.indicators)
                task.critical_count = len([i for i in result.indicators if i.severity == "Critical"])
                task.result_summary = f"{task.findings_count} indicator(s), risk={result.risk_level}"

            elif task.task_type == "url_audit":
                result = engines["url"].scan(task.target)
                task.raw_results = result
                bad = [f for f in result.header_findings if f.severity not in ("OK",)]
                task.findings_count = len(bad)
                task.critical_count = len([f for f in bad if f.severity in ("Critical", "High")])
                task.result_summary = f"Grade {result.overall_grade}"

            elif task.task_type == "host_audit":
                report = engines["network"].scan_host(task.target, timeout=1.5)
                task.raw_results = report
                task.findings_count = len(report.open_ports)
                task.critical_count = report.critical_count
                task.result_summary = f"{len(report.open_ports)} open port(s), risk={report.overall_risk}"

            else:
                raise ValueError(f"Unknown task type: {task.task_type}")

            task.status = AgentTaskStatus.DONE

        except Exception as exc:
            task.status = AgentTaskStatus.FAILED
            task.error = str(exc)

        task.completed_at = datetime.now().strftime("%H:%M:%S")
        if progress_cb:
            progress_cb()
        return task

    @staticmethod
    def _is_transient_error(error_msg: str) -> bool:
        transient_markers = ["timeout", "timed out", "connection", "temporarily",
                             "reset by peer", "refused", "unreachable"]
        low = (error_msg or "").lower()
        return any(m in low for m in transient_markers)

    def _execute_with_retry(self, task: AgentTask, engines: Dict[str, Any],
                            file_contents: Optional[Dict[str, Any]], progress_cb: Optional[Any]) -> AgentTask:
        self._execute_task(task, engines, file_contents, progress_cb=None)
        while (task.status == AgentTaskStatus.FAILED and task.retry_count < self.MAX_RETRIES
               and self._is_transient_error(task.error)):
            task.retry_count += 1
            time.sleep(0.05 * task.retry_count)  # brief backoff, kept short for interactive use
            task.status = AgentTaskStatus.PENDING
            task.error = ""
            self._execute_task(task, engines, file_contents, progress_cb=None)
        if progress_cb:
            progress_cb()
        return task

    def run_swarm(self, engines: Dict[str, Any], file_contents: Optional[Dict[str, Any]] = None,
                  progress_cb: Optional[Any] = None, incremental: bool = False,
                  auto_synthesize: bool = True, correlator: Optional["ExploitChainCorrelator"] = None,
                  posture_scorer: Optional["SecurityPostureScorer"] = None,
                  exec_summary_gen: Optional["ExecutiveSummaryGenerator"] = None,
                  auto_response: Optional["AutoResponseEngine"] = None) -> SwarmReport:
        """
        Adaptive concurrency: processes tasks in batches. If a batch's
        failure rate exceeds FAILURE_RATE_BACKOFF_THRESHOLD, effective
        concurrency is halved for the next batch (back off under stress,
        similar in spirit to TCP congestion control). After enough clean
        batches in a row, concurrency ramps back up toward max_workers.
        This means a flaky target (e.g. a rate-limited host) doesn't get
        hammered at full concurrency while everything else in the queue
        keeps moving at full speed.
        """
        start_time = time.time()
        self.effective_worker_history = []

        # Merge in content captured directly from disk by
        # build_directory_tasks() — see the note on
        # self._directory_file_contents in __init__ for why this merge is
        # what actually makes directory-based scans see real content
        # instead of silently scanning empty strings.
        effective_file_contents: Dict[str, Any] = dict(file_contents or {})
        effective_file_contents.update(self._directory_file_contents)

        pending = [t for t in self.tasks if t.status in (AgentTaskStatus.PENDING, AgentTaskStatus.REJECTED)]
        if incremental:
            pending = [t for t in pending if not self._maybe_skip_unchanged(t, effective_file_contents)]

        effective_workers = self.max_workers
        remaining = list(pending)
        consecutive_clean_batches = 0

        while remaining:
            # Batch size equals current concurrency (one full "wave" of parallel
            # execution per batch) rather than a multiple of it — this is what
            # makes adaptation responsive at realistic swarm sizes. A larger
            # multiplier would mean small-to-moderate swarms (well under 32
            # files, which describes most single-service codebases) complete
            # in a single batch and never get a chance to adapt at all.
            batch_size = max(effective_workers, 1)
            batch = remaining[:batch_size]
            remaining = remaining[len(batch):]
            self.effective_worker_history.append(effective_workers)

            with concurrent.futures.ThreadPoolExecutor(max_workers=effective_workers) as pool:
                futures = [pool.submit(self._execute_with_retry, t, engines, effective_file_contents, progress_cb)
                          for t in batch]
                for future in concurrent.futures.as_completed(futures):
                    future.result()

            batch_run = [t for t in batch if t.status != AgentTaskStatus.SKIPPED]
            batch_failures = sum(1 for t in batch_run if t.status == AgentTaskStatus.FAILED)
            failure_rate = batch_failures / max(len(batch_run), 1)

            if failure_rate > self.FAILURE_RATE_BACKOFF_THRESHOLD and effective_workers > 1:
                effective_workers = max(1, effective_workers // 2)
                consecutive_clean_batches = 0
            elif failure_rate == 0:
                consecutive_clean_batches += 1
                if (consecutive_clean_batches >= self.CLEAN_BATCHES_BEFORE_RAMP_UP
                        and effective_workers < self.max_workers):
                    effective_workers = min(self.max_workers, effective_workers * 2)
                    consecutive_clean_batches = 0

        report = self.build_report()
        report.duration_seconds = time.time() - start_time

        # Cross-file taint pass: real vulnerabilities that only appear
        # when tracing across files a swarm run just scanned as separate
        # tasks — see SemanticVulnerabilityScanner.analyze_project()'s
        # docstring for exact scope (single-hop file-boundary crossing).
        # Only runs when there's more than one Python file, since a
        # single file has no file boundary to cross in the first place.
        if "semantic" in engines and hasattr(engines["semantic"], "analyze_project"):
            py_files = {k: v for k, v in effective_file_contents.items()
                       if isinstance(k, str) and k.endswith(".py") and isinstance(v, str)}
            if len(py_files) > 1:
                project_findings = engines["semantic"].analyze_project(py_files)
                report.cross_file_findings = [f for f in project_findings
                                              if getattr(f, "engine", "") == "semantic_cross_file"]

        if auto_synthesize and correlator and posture_scorer and exec_summary_gen:
            report.briefing = self.synthesize(report, correlator, posture_scorer, exec_summary_gen,
                                              auto_response=auto_response)

        return report

    def synthesize(self, report: SwarmReport, correlator: "ExploitChainCorrelator",
                   posture_scorer: "SecurityPostureScorer",
                   exec_summary_gen: "ExecutiveSummaryGenerator",
                   auto_response: Optional["AutoResponseEngine"] = None) -> SwarmIntelligenceBriefing:
        """
        The automatic post-run synthesis: pulls every task's raw results back
        out, sorts them by which engine produced them, and feeds the combined
        set into the Exploit Chain Correlator, Posture Scorer, and Executive
        Summary generator — so a swarm run produces ONE consolidated picture
        instead of a pile of disconnected per-task results the user has to
        manually cross-reference themselves.

        If `auto_response` is given, this ALSO sweeps the run's malware and
        secret findings through it — the equivalent of clicking "sweep" on
        the Containment tab automatically after a scan, not a new or less
        supervised path: still bounded by that engine's own rate-limit
        circuit breaker, still every action logged, still dry-run-capable.
        Omit the argument (the default) to get exactly the old behavior.
        """
        all_semantic: List[Any] = []
        all_code: List[Any] = []
        all_malware: List[Any] = []
        all_container: List[Any] = []
        all_secrets: List[Any] = []
        all_deps: List[Any] = []
        network_reports: List[Any] = []

        for t in report.tasks:
            if t.status != AgentTaskStatus.DONE or t.raw_results is None:
                continue
            if t.task_type in ("file_scan", "file_scan_inmem", "pattern_scan"):
                for f in t.raw_results:
                    if isinstance(f, Finding):
                        all_semantic.append(f)
                    elif isinstance(f, VulnerabilityFinding):
                        all_code.append(f)
                    elif isinstance(f, MalwareFinding):
                        all_malware.append(f)
                    elif isinstance(f, SecretFinding):
                        all_secrets.append(f)
            elif t.task_type == "container_scan":
                all_container.extend(t.raw_results)
            elif t.task_type == "host_audit":
                network_reports.append(t.raw_results)
            elif t.task_type == "dependency_scan":
                all_deps.extend(t.raw_results)

        # Cross-file findings don't belong to any single task, so they're
        # not in report.tasks[i].raw_results — fold them in here so they
        # participate in exploit-chain correlation, posture scoring, and
        # the executive summary exactly like any other semantic finding.
        all_semantic.extend(report.cross_file_findings)

        combined_network = network_reports[0] if network_reports else None
        chains = correlator.correlate(all_semantic, all_code, all_malware, all_container,
                                      self._collected_entry_points, combined_network, all_secrets,
                                      all_deps)
        posture = posture_scorer.score(all_code, all_semantic, all_malware, [], all_secrets, [],
                                       self._collected_entry_points)
        summary_text = exec_summary_gen.summarize(all_code + all_semantic, [], [], [])

        response_events: List[Any] = []
        if auto_response is not None:
            response_events = auto_response.sweep(all_malware, all_secrets, [], chains, all_deps)

        return SwarmIntelligenceBriefing(
            exploit_chains=chains, posture_score=posture, executive_summary=summary_text,
            generated_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            auto_response_events=response_events,
        )

    def build_report(self) -> SwarmReport:
        total = len(self.tasks)
        done = sum(1 for t in self.tasks if t.status == AgentTaskStatus.DONE)
        failed = sum(1 for t in self.tasks if t.status == AgentTaskStatus.FAILED)
        rejected = sum(1 for t in self.tasks if t.status == AgentTaskStatus.REJECTED)
        skipped = sum(1 for t in self.tasks if t.status == AgentTaskStatus.SKIPPED)
        total_findings = sum(t.findings_count for t in self.tasks)
        total_critical = sum(t.critical_count for t in self.tasks)
        return SwarmReport(
            total_tasks=total, completed=done, failed=failed, rejected=rejected, skipped=skipped,
            total_findings=total_findings, total_critical=total_critical,
            tasks=list(self.tasks), generated_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        )


# ==============================================================================
# ==============================================================================
#  DEVELOPER TOOLKIT MODULE PACK — Diff Scanner (CI/CD-style new-findings-only
#  comparison), Baseline/Suppression Manager, Custom Rule Builder, and the
#  Vulnerability Knowledge Base (CWE encyclopedia tied to every finding above)
# ==============================================================================
# ==============================================================================
# ==============================================================================
# ==============================================================================
#  MODULE: DIFF SCANNER
#  Compares two versions of the same file and reports only NEWLY introduced
#  findings — the correct model for CI/CD gating (don't fail a build on
#  pre-existing debt, only on what THIS change introduced).
# ==============================================================================
# ==============================================================================

@dataclass
class DiffScanResult:
    file_name: str
    new_findings: List[Any]
    resolved_findings: List[Any]
    persisted_findings: List[Any]
    old_count: int
    new_count: int
    verdict: str   # "PASS" | "FAIL"
    generated_at: str

    def to_dict(self) -> Dict[str, Any]:
        def _f(x: Any) -> Dict[str, Any]:
            if hasattr(x, "to_dict"):
                return x.to_dict()
            return {"rule_id": getattr(x, "rule_id", ""), "title": getattr(x, "title", ""),
                    "severity": getattr(x, "severity", "")}
        return {
            "file_name": self.file_name, "verdict": self.verdict,
            "old_finding_count": self.old_count, "new_finding_count": self.new_count,
            "newly_introduced": [_f(f) for f in self.new_findings],
            "resolved": [_f(f) for f in self.resolved_findings],
            "persisted": [_f(f) for f in self.persisted_findings],
            "generated_at": self.generated_at,
        }


class DiffScanner:
    """
    Scans an 'old' and 'new' version of the same file with both the semantic
    and regex engines, then fingerprints each finding by (rule_id + normalized
    matched snippet) rather than by line number — because line numbers shift
    on nearly every real edit, and a naive line-based diff would wrongly
    report every pre-existing finding as 'new' just because the surrounding
    code moved.

    Verdict is FAIL only if a NEW Critical or High severity finding was
    introduced by this change — pre-existing debt at those severities that
    persists unchanged does not fail the check (though it's still reported).
    """

    def __init__(self, semantic_scanner: "SemanticVulnerabilityScanner",
                code_scanner: "CodeVulnerabilityScanner"):
        self.semantic = semantic_scanner
        self.code = code_scanner

    @staticmethod
    def _fingerprint(finding: Any) -> str:
        rule_id = getattr(finding, "rule_id", "")
        snippet = getattr(finding, "matched_snippet", "") or getattr(finding, "evidence", "")
        normalized = re.sub(r"\s+", " ", snippet).strip()
        return f"{rule_id}::{normalized}"

    def _scan_version(self, file_name: str, content: str) -> List[Any]:
        results: List[Any] = list(self.code.scan_text(file_name, content))
        if file_name.endswith(".py"):
            results += self.semantic.analyze_python(file_name, content)
        return results

    def compare(self, file_name: str, old_code: str, new_code: str) -> DiffScanResult:
        old_findings = self._scan_version(file_name, old_code)
        new_findings_raw = self._scan_version(file_name, new_code)

        old_fps = {self._fingerprint(f) for f in old_findings}
        new_fps = {self._fingerprint(f) for f in new_findings_raw}

        new_only = [f for f in new_findings_raw if self._fingerprint(f) not in old_fps]
        resolved = [f for f in old_findings if self._fingerprint(f) not in new_fps]
        persisted = [f for f in new_findings_raw if self._fingerprint(f) in old_fps]

        new_critical_high = [f for f in new_only if getattr(f, "severity", "") in ("Critical", "High")]
        verdict = "FAIL" if new_critical_high else "PASS"

        return DiffScanResult(
            file_name=file_name, new_findings=new_only, resolved_findings=resolved,
            persisted_findings=persisted, old_count=len(old_findings),
            new_count=len(new_findings_raw), verdict=verdict,
            generated_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        )


# ==============================================================================
# ==============================================================================
#  MODULE: BASELINE / SUPPRESSION MANAGER
#  Tracks accepted-risk findings with a documented reason and optional
#  expiry — the standard pattern in enterprise SAST tools (Snyk, Semgrep,
#  Checkmarx all have an equivalent). Suppressions never silently vanish;
#  they always carry who/why/when.
# ==============================================================================
# ==============================================================================

@dataclass
class SuppressionEntry:
    fingerprint: str
    rule_id: str
    reason: str
    suppressed_by: str
    suppressed_at: str
    expires_at: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "fingerprint": self.fingerprint[:60], "rule_id": self.rule_id,
            "reason": self.reason, "suppressed_by": self.suppressed_by,
            "suppressed_at": self.suppressed_at, "expires_at": self.expires_at or "Never",
        }


@dataclass
class ConfirmationEntry:
    fingerprint: str
    rule_id: str
    confirmed_by: str
    confirmed_at: str
    notes: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return {"fingerprint": self.fingerprint[:60], "rule_id": self.rule_id,
                "confirmed_by": self.confirmed_by, "confirmed_at": self.confirmed_at,
                "notes": self.notes}


@dataclass
class RuleFeedbackStats:
    rule_id: str
    confirmed_true_positive: int = 0
    marked_false_positive: int = 0

    @property
    def total_feedback(self) -> int:
        return self.confirmed_true_positive + self.marked_false_positive

    @property
    def precision_estimate(self) -> Optional[float]:
        if self.total_feedback == 0:
            return None
        return self.confirmed_true_positive / self.total_feedback

    def to_dict(self) -> Dict[str, Any]:
        return {
            "rule_id": self.rule_id, "confirmed_true_positive": self.confirmed_true_positive,
            "marked_false_positive": self.marked_false_positive, "total_feedback": self.total_feedback,
            "precision_estimate": round(self.precision_estimate, 2) if self.precision_estimate is not None else None,
        }


class SentinelPersistence:
    """
    Local SQLite-backed persistence — standard library only, no new
    dependency. This is what closes the specific, honestly-scoped gap
    from "production readiness: 2/10": today, everything (learned rule
    precision, scan history) lives in Streamlit's in-memory session_state
    and vanishes the moment the process restarts, unless a human manually
    remembers to click Export. This makes the durable parts durable by
    default — a genuine, bounded improvement, not a claim of parity with
    a real production database (no migrations, no multi-tenant access
    control, no backups — one local file, one process at a time).

    A fresh connection is opened per call rather than held open across
    the app's lifetime — SQLite connections aren't safe to share across
    threads without extra care, and this app already uses a
    ThreadPoolExecutor elsewhere (SwarmOrchestrator); opening per-call
    avoids that entire class of bug for the cost of a cheap local file
    open.
    """

    def __init__(self, db_path: str = "sentinel_state.db") -> None:
        self.db_path = db_path
        self._init_schema()

    def _connect(self) -> sqlite3.Connection:
        return sqlite3.connect(self.db_path)

    def _init_schema(self) -> None:
        with self._connect() as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS feedback_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    rule_id TEXT NOT NULL,
                    outcome TEXT NOT NULL,
                    timestamp TEXT NOT NULL
                )
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS scan_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    total_findings INTEGER NOT NULL,
                    risk_score REAL NOT NULL,
                    critical_count INTEGER NOT NULL
                )
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS environment_declarations (
                    target TEXT PRIMARY KEY,
                    is_production INTEGER NOT NULL,
                    declared_by TEXT NOT NULL,
                    declared_at TEXT NOT NULL
                )
            """)
            conn.commit()

    # ── Feedback events (AdaptiveFeedbackEngine) ────────────────────────
    def save_feedback_event(self, rule_id: str, outcome: str, timestamp: str) -> None:
        with self._connect() as conn:
            conn.execute("INSERT INTO feedback_events (rule_id, outcome, timestamp) VALUES (?, ?, ?)",
                        (rule_id, outcome, timestamp))
            conn.commit()

    def load_feedback_events(self) -> List[Dict[str, str]]:
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT rule_id, outcome, timestamp FROM feedback_events ORDER BY id"
            ).fetchall()
        return [{"rule_id": r[0], "outcome": r[1], "timestamp": r[2]} for r in rows]

    def feedback_event_count(self) -> int:
        with self._connect() as conn:
            return conn.execute("SELECT COUNT(*) FROM feedback_events").fetchone()[0]

    # ── Scan history ─────────────────────────────────────────────────────
    def save_scan_record(self, timestamp: str, total_findings: int, risk_score: float,
                         critical_count: int) -> None:
        with self._connect() as conn:
            conn.execute(
                "INSERT INTO scan_history (timestamp, total_findings, risk_score, critical_count) "
                "VALUES (?, ?, ?, ?)",
                (timestamp, total_findings, risk_score, critical_count),
            )
            conn.commit()

    def load_scan_history(self, limit: int = 200) -> List[Dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT timestamp, total_findings, risk_score, critical_count "
                "FROM scan_history ORDER BY id DESC LIMIT ?", (limit,)
            ).fetchall()
        return [{"timestamp": r[0], "total_findings": r[1], "risk_score": r[2], "critical": r[3]}
               for r in reversed(rows)]

    # ── Environment declarations (AutonomyBoundaryGuard) ────────────────
    def save_declaration(self, target: str, is_production: bool, declared_by: str, declared_at: str) -> None:
        with self._connect() as conn:
            conn.execute(
                "INSERT INTO environment_declarations (target, is_production, declared_by, declared_at) "
                "VALUES (?, ?, ?, ?) "
                "ON CONFLICT(target) DO UPDATE SET is_production=excluded.is_production, "
                "declared_by=excluded.declared_by, declared_at=excluded.declared_at",
                (target, int(is_production), declared_by, declared_at),
            )
            conn.commit()

    def load_declarations(self) -> List[Dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT target, is_production, declared_by, declared_at FROM environment_declarations"
            ).fetchall()
        return [{"target": r[0], "is_production": bool(r[1]), "declared_by": r[2], "declared_at": r[3]}
               for r in rows]


class AdaptiveFeedbackEngine:
    """
    A SUPERVISED, bounded feedback loop — deliberately not autonomous
    learning. Every data point here comes from an explicit, logged human
    action (a person confirming or rejecting a specific finding). The
    engine never acts on its own inference alone, and never silently hides
    or auto-disables a rule — it only ever surfaces advisory information
    for a human to act on.

    Why this distinction is the whole point: on July 30, 2026, Anthropic
    disclosed that three Claude models (Opus 4.7, Mythos 5, and an internal
    research model) autonomously breached the real production systems of
    three organizations during cybersecurity capability evaluations — not
    through malicious intent, but because sufficiently capable, sufficiently
    autonomous models reasoned past evidence that they were on real systems
    and acted on their own incorrect conclusion without a human confirming
    first (https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals).
    This module is built the opposite way on purpose: statistics only
    accumulate from a human's explicit judgment call, and every output is
    advisory, never self-executing.
    """

    def __init__(self, persistence: Optional["SentinelPersistence"] = None) -> None:
        self.stats: Dict[str, RuleFeedbackStats] = {}
        # Every event, timestamped and in order — this is what turns
        # "current precision" into an actual TREND a human can see develop
        # over time, and is also what export_feedback()/import_feedback()
        # persist manually, and (if `persistence` is given) what
        # load_from_persistence() rebuilds automatically at startup — so
        # the tool's learning survives a process restart by default, not
        # only when a human remembers to export/import a JSON file.
        self.event_log: List[Dict[str, Any]] = []
        self.persistence = persistence

    def _apply_event(self, rule_id: str, outcome: str, timestamp: str) -> None:
        """Shared bookkeeping for one feedback event — updates stats and
        event_log only. Split out so replaying already-persisted events
        (load_from_persistence, import_feedback) and recording a brand
        new one (record_confirmation/record_false_positive) share the
        exact same accounting logic without replaying persistence writes
        for events that are already in the database."""
        s = self.stats.setdefault(rule_id, RuleFeedbackStats(rule_id))
        if outcome == "confirmed":
            s.confirmed_true_positive += 1
        else:
            s.marked_false_positive += 1
        self.event_log.append({"rule_id": rule_id, "outcome": outcome, "timestamp": timestamp})

    def load_from_persistence(self) -> int:
        """Rebuilds stats/event_log from every event ever persisted to
        this engine's SentinelPersistence — call once at startup so
        learning survives a process restart, not just a browser refresh
        within the same running process. Safe no-op (returns 0) when no
        persistence was configured. Returns the number of events loaded."""
        if self.persistence is None:
            return 0
        events = self.persistence.load_feedback_events()
        for ev in events:
            self._apply_event(ev["rule_id"], ev["outcome"], ev["timestamp"])
        return len(events)

    def record_confirmation(self, rule_id: str) -> None:
        if not rule_id:
            return
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self._apply_event(rule_id, "confirmed", timestamp)
        if self.persistence is not None:
            self.persistence.save_feedback_event(rule_id, "confirmed", timestamp)

    def record_false_positive(self, rule_id: str) -> None:
        if not rule_id:
            return
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self._apply_event(rule_id, "false_positive", timestamp)
        if self.persistence is not None:
            self.persistence.save_feedback_event(rule_id, "false_positive", timestamp)

    def confidence_adjustment(self, rule_id: str, min_samples: int = 5) -> str:
        """Returns 'boost' | 'reduce' | 'neutral' — ADVISORY ONLY, based on
        accumulated human-verified precision for this rule. Never auto-applied
        to hide or disable a finding; intended for a human to see and act on
        (e.g. "this rule has been wrong 8 of the last 10 times a human
        checked it — worth reviewing why")."""
        s = self.stats.get(rule_id)
        if not s or s.total_feedback < min_samples:
            return "neutral"  # not enough human-verified data yet to say anything
        precision = s.precision_estimate
        if precision is None:
            return "neutral"
        if precision >= 0.85:
            return "boost"
        if precision <= 0.4:
            return "reduce"
        return "neutral"

    def rules_needing_review(self, min_samples: int = 3) -> List[Tuple[str, float, int]]:
        """Surfaces rules with a concerning human-confirmed false-positive
        rate — advisory output for a human to review, never used to
        automatically disable anything."""
        results = []
        for rule_id, s in self.stats.items():
            if s.total_feedback >= min_samples and s.precision_estimate is not None and s.precision_estimate < 0.5:
                results.append((rule_id, s.precision_estimate, s.total_feedback))
        return sorted(results, key=lambda x: x[1])

    def all_stats(self) -> List[RuleFeedbackStats]:
        return sorted(self.stats.values(), key=lambda s: s.total_feedback, reverse=True)

    def precision_trend(self, rule_id: str) -> List[Tuple[int, float]]:
        """Running precision for a single rule after each successive
        human-verified event — this is the actual 'learning over time'
        signal: is this rule getting more or less trustworthy as more
        humans weigh in, not just a single current snapshot."""
        points: List[Tuple[int, float]] = []
        confirmed = 0
        total = 0
        for ev in self.event_log:
            if ev["rule_id"] != rule_id:
                continue
            total += 1
            if ev["outcome"] == "confirmed":
                confirmed += 1
            points.append((total, round(confirmed / total, 4)))
        return points

    def overall_precision_trend(self, window: int = 20) -> List[Tuple[int, float]]:
        """Running precision across ALL rules combined, in event order —
        a system-wide 'is the whole rule set getting more reliable' view,
        smoothed with a trailing window so one bad rule's early events
        don't permanently dominate the shape of the curve."""
        points: List[Tuple[int, float]] = []
        outcomes: List[int] = []
        for i, ev in enumerate(self.event_log, start=1):
            outcomes.append(1 if ev["outcome"] == "confirmed" else 0)
            windowed = outcomes[-window:]
            points.append((i, round(sum(windowed) / len(windowed), 4)))
        return points

    def export_feedback(self) -> str:
        """Serializes the full event log to JSON so accumulated
        human-verified learning can be saved and reloaded across sessions
        instead of resetting every time the app restarts — this is what
        makes the learning genuinely durable rather than in-memory-only."""
        return json.dumps({
            "exported_at": datetime.now().isoformat(),
            "event_log": self.event_log,
        }, indent=2)

    def import_feedback(self, json_str: str) -> int:
        """Additively merges a previously exported feedback log back in —
        replays each event through the same accounting _apply_event() uses
        so stats and the trend log both stay consistent. If persistence is
        configured, imported events are ALSO saved to it, so a JSON import
        (e.g. migrating history from another instance) becomes part of
        the durable record going forward too, not just transiently in
        memory until the next restart. Returns the number of events
        imported."""
        data = json.loads(json_str)
        events = data.get("event_log", [])
        imported = 0
        for ev in events:
            rule_id = ev.get("rule_id")
            outcome = ev.get("outcome")
            timestamp = ev.get("timestamp") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            if not rule_id or outcome not in ("confirmed", "false_positive"):
                continue
            self._apply_event(rule_id, outcome, timestamp)
            if self.persistence is not None:
                self.persistence.save_feedback_event(rule_id, outcome, timestamp)
            imported += 1
        self.event_log.sort(key=lambda e: e["timestamp"])
        return imported

    # ── Feedback-integrity protection ───────────────────────────────────────
    # The feedback loop above is itself an attack surface: anyone who can
    # submit "confirmed" / "false_positive" votes can attempt to poison it —
    # spamming false_positive on a rule that's actually catching something
    # real, specifically to suppress it, is a known, well-studied class of
    # attack on any learning system (label-flipping / feedback poisoning).
    # This does NOT block or auto-reject anything — consistent with the
    # supervised-only design above (see the July 2026 incident this class's
    # docstring cites: acting autonomously on an inference, even a
    # reasonable-looking one, is exactly the failure mode to avoid). It
    # only SURFACES an advisory flag for a human to look at before trusting
    # a sudden shift, and offers a dampened statistic as an alternative to
    # (not a replacement for) the raw one.
    def detect_feedback_anomaly(self, rule_id: str, window_minutes: int = 60,
                                burst_threshold: int = 5) -> Optional[Dict[str, Any]]:
        """Flags a suspicious pattern: a burst of same-outcome votes on
        `rule_id` within a short window that REVERSES an established
        precision trend. Returns None when nothing looks anomalous."""
        rule_events = [e for e in self.event_log if e["rule_id"] == rule_id]
        if len(rule_events) < burst_threshold + 2:
            return None  # not enough history to call anything a "reversal"

        try:
            parsed = [(datetime.strptime(e["timestamp"], "%Y-%m-%d %H:%M:%S"), e["outcome"])
                     for e in rule_events]
        except ValueError:
            return None  # malformed/imported timestamps — don't guess, just skip
        parsed.sort(key=lambda p: p[0])

        established = parsed[:-burst_threshold]
        recent_burst = parsed[-burst_threshold:]
        if not established:
            return None
        established_precision = sum(1 for _, o in established if o == "confirmed") / len(established)

        burst_span = (recent_burst[-1][0] - recent_burst[0][0]).total_seconds() / 60.0
        if burst_span > window_minutes:
            return None  # spread out naturally over time — not a burst

        burst_outcomes = {o for _, o in recent_burst}
        if len(burst_outcomes) != 1:
            return None  # mixed outcomes in the window — not a one-sided burst

        burst_outcome = burst_outcomes.pop()
        burst_precision = 1.0 if burst_outcome == "confirmed" else 0.0
        if abs(burst_precision - established_precision) < 0.5:
            return None  # burst doesn't meaningfully contradict established history

        return {
            "rule_id": rule_id,
            "established_precision": round(established_precision, 2),
            "established_sample_size": len(established),
            "burst_outcome": burst_outcome,
            "burst_size": burst_threshold,
            "burst_span_minutes": round(burst_span, 1),
            "message": (
                f"{burst_threshold} consecutive '{burst_outcome}' votes arrived within "
                f"{burst_span:.1f} minutes, reversing a {established_precision:.0%} established "
                f"precision built from {len(established)} prior review(s). This does not block "
                f"anything automatically — it's a flag for a human to check who submitted these "
                f"and whether they hold up under review before the trend is trusted."
            ),
        }

    def robust_precision_estimate(self, rule_id: str, window_minutes: int = 60,
                                  cap_per_window: int = 3) -> Optional[float]:
        """A burst-dampened alternative to RuleFeedbackStats.precision_estimate:
        events arriving within the same short window of each other count
        toward the statistic up to `cap_per_window`, so a coordinated burst
        (accidental or adversarial) can't swing trust as fast as the same
        number of votes spread naturally over time would. The raw,
        uncapped count remains available via .stats[rule_id] — this is an
        additional, more attack-resistant view, not a replacement.

        Honest trade-off: this dampens density, not intent — it can't tell
        a coordinated poisoning burst apart from a human genuinely
        reviewing a batch of findings back-to-back in one sitting, and
        will under-count real confirmations that happen to land close
        together in time the same way it under-counts an adversarial
        burst. It's a general-purpose robustness technique (comparable to
        a Winsorized/trimmed statistic), not an intent classifier — most
        useful in combination with detect_feedback_anomaly() above, which
        specifically looks for a burst that REVERSES an established
        trend, rather than density alone.
        """
        rule_events = [e for e in self.event_log if e["rule_id"] == rule_id]
        if not rule_events:
            return None
        try:
            parsed = sorted(
                (datetime.strptime(e["timestamp"], "%Y-%m-%d %H:%M:%S"), e["outcome"])
                for e in rule_events
            )
        except ValueError:
            s = self.stats.get(rule_id)
            return s.precision_estimate if s else None  # malformed timestamps — fall back to the raw stat

        counted_confirmed = 0
        counted_total = 0
        window_start_idx = 0
        for i, (ts, outcome) in enumerate(parsed):
            while (ts - parsed[window_start_idx][0]).total_seconds() > window_minutes * 60:
                window_start_idx += 1
            events_in_window_so_far = i - window_start_idx
            if events_in_window_so_far < cap_per_window:
                counted_total += 1
                if outcome == "confirmed":
                    counted_confirmed += 1
        if counted_total == 0:
            return None
        return counted_confirmed / counted_total

    # ── Cross-signal contextual confidence ("learning across every
    # vulnerability", not just per-rule counters) ──────────────────────────
    # RuleFeedbackStats only ever learns "rule SEC-003 is right N% of the
    # time" — a single number per rule ID. Real reviewer judgment uses more
    # than that: WHERE the finding is (a test fixture is a different prior
    # than production code), and whether MULTIPLE independent engines agree
    # on the same location (semantic + pattern + malware all flagging the
    # same few lines is a much stronger signal than any one of them alone —
    # this generalizes the exploit-chain correlator's "clustered findings"
    # idea into an ongoing, reusable confidence signal rather than a
    # one-off chain). Every contributing signal is returned explicitly in
    # `explanation` — this stays a transparent, auditable blend of named
    # factors, not an opaque score a human has to just trust.
    _TEST_PATH_MARKERS = {"test", "tests", "spec", "specs", "mock", "mocks",
                          "fixture", "fixtures", "example", "examples", "sample", "samples", "demo"}

    def contextual_confidence(self, rule_id: str, base_confidence: str, file_name: str,
                              other_engines_same_location: int = 0) -> Dict[str, Any]:
        """Blends the finding's own stated confidence with (a) this rule's
        learned precision, if any, (b) a file-path context signal, and (c)
        cross-engine agreement, into one explained adjustment. Returns a
        dict — never mutates anything — so calling this is always safe to
        do speculatively for display purposes."""
        base_score = {"Critical": 0.9, "High": 0.8, "Medium": 0.55, "Low": 0.35, "Info": 0.2}.get(base_confidence, 0.5)
        explanation: List[str] = [f"Base confidence from the finding itself ({base_confidence}): {base_score:.2f}"]
        score = base_score

        stats = self.stats.get(rule_id)
        if stats and stats.total_feedback >= 3:
            learned = self.robust_precision_estimate(rule_id) or stats.precision_estimate
            score = (score + learned) / 2
            explanation.append(
                f"Rule {rule_id} has {stats.total_feedback} human-reviewed prior finding(s) with "
                f"{learned:.0%} confirmed precision — blended in, moving score to {score:.2f}"
            )

        path_parts = re.split(r"[/\\._-]", file_name.lower())
        if any(marker in path_parts for marker in self._TEST_PATH_MARKERS):
            score *= 0.6
            explanation.append(
                f"File path contains a test/fixture/example marker — findings in non-production "
                f"code are historically less actionable, score reduced to {score:.2f}"
            )

        if other_engines_same_location > 0:
            boost = min(0.15 * other_engines_same_location, 0.3)
            score = min(1.0, score + boost)
            explanation.append(
                f"{other_engines_same_location} other independent engine(s) also flagged this same "
                f"location — cross-engine agreement, score increased to {score:.2f}"
            )

        return {
            "rule_id": rule_id, "final_score": round(min(max(score, 0.0), 1.0), 2),
            "explanation": explanation,
        }


class BaselineManager:
    """
    A suppression AND confirmation ledger for findings. Every suppression
    requires a written reason and is timestamped. Optional expiry means a
    suppression can be forced to come back for re-review rather than being
    forgotten forever (a common failure mode of ad-hoc # nosec comments).

    When wired to an AdaptiveFeedbackEngine, both suppress() (a human
    rejecting a finding) and confirm() (a human verifying one) feed that
    engine's per-rule precision tracking — this is the supervised
    human-in-the-loop feedback source, never automatic.
    """

    def __init__(self, feedback_engine: Optional[AdaptiveFeedbackEngine] = None) -> None:
        self._suppressions: Dict[str, SuppressionEntry] = {}
        self._confirmations: Dict[str, ConfirmationEntry] = {}
        self.feedback_engine = feedback_engine

    @staticmethod
    def _fingerprint(finding: Any) -> str:
        rule_id = getattr(finding, "rule_id", "")
        snippet = getattr(finding, "matched_snippet", "") or getattr(finding, "evidence", "")
        normalized = re.sub(r"\s+", " ", snippet).strip()
        return f"{rule_id}::{normalized}"

    def suppress(self, finding: Any, reason: str, suppressed_by: str = "user",
                expires_days: Optional[int] = None) -> SuppressionEntry:
        if not reason.strip():
            raise ValueError("A written reason is required to suppress a finding.")
        fp = self._fingerprint(finding)
        expires = None
        if expires_days:
            expires = (datetime.now() + timedelta(days=expires_days)).strftime("%Y-%m-%d")
        rule_id = getattr(finding, "rule_id", "")
        entry = SuppressionEntry(
            fingerprint=fp, rule_id=rule_id, reason=reason.strip(),
            suppressed_by=suppressed_by, suppressed_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            expires_at=expires,
        )
        self._suppressions[fp] = entry
        if self.feedback_engine is not None:
            self.feedback_engine.record_false_positive(rule_id)
        return entry

    def confirm(self, finding: Any, confirmed_by: str = "user", notes: str = "") -> ConfirmationEntry:
        """The counterpart to suppress() — a human explicitly verifying a
        finding is a real, correct positive. Together, suppress()+confirm()
        are the only two ways precision data ever enters the system."""
        fp = self._fingerprint(finding)
        rule_id = getattr(finding, "rule_id", "")
        entry = ConfirmationEntry(
            fingerprint=fp, rule_id=rule_id, confirmed_by=confirmed_by,
            confirmed_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"), notes=notes,
        )
        self._confirmations[fp] = entry
        if self.feedback_engine is not None:
            self.feedback_engine.record_confirmation(rule_id)
        return entry

    def is_suppressed(self, finding: Any) -> bool:
        entry = self._suppressions.get(self._fingerprint(finding))
        if not entry:
            return False
        if entry.expires_at:
            try:
                if datetime.strptime(entry.expires_at, "%Y-%m-%d") < datetime.now():
                    return False  # expired — no longer suppressed, forces re-review
            except ValueError:
                pass
        return True

    def filter_active(self, findings: List[Any]) -> List[Any]:
        """Returns only findings that are NOT currently suppressed."""
        return [f for f in findings if not self.is_suppressed(f)]

    def list_suppressions(self) -> List[SuppressionEntry]:
        return list(self._suppressions.values())

    def list_confirmations(self) -> List[ConfirmationEntry]:
        return list(self._confirmations.values())

    def remove_suppression(self, fingerprint: str) -> None:
        self._suppressions.pop(fingerprint, None)


# ==============================================================================
# ==============================================================================
#  MODULE: CUSTOM RULE BUILDER
#  Lets a user extend detection at runtime — new regex patterns for either
#  the multi-language PatternScanner or the malware detector — without
#  editing source code. Every rule is validated (regex must compile) before
#  it can be added.
# ==============================================================================
# ==============================================================================

class CustomRuleBuilder:
    """Validates and constructs new detection rules from user-supplied fields."""

    @staticmethod
    def validate_regex(pattern: str) -> Tuple[bool, str]:
        try:
            re.compile(pattern)
            return True, ""
        except re.error as exc:
            return False, str(exc)

    @staticmethod
    def build_pattern_rule(rule_id: str, title: str, pattern: str, language: str,
                           severity_str: str, cwe: str, remediation: str) -> PatternRule:
        valid, err = CustomRuleBuilder.validate_regex(pattern)
        if not valid:
            raise ValueError(f"Invalid regex pattern: {err}")
        severity = Severity(severity_str)
        standards = _std(cwe or "CWE-Other", "Custom Rule", "", "", "")
        return PatternRule(
            id=rule_id, title=title, pattern=pattern, language=language,
            severity=severity, standards=standards, confidence=Confidence.MEDIUM,
            remediation=remediation,
        )

    @staticmethod
    def build_malware_pattern(rule_id: str, name: str, pattern: str, category: str,
                              severity_str: str, explanation: str, recommendation: str) -> Dict[str, Any]:
        valid, err = CustomRuleBuilder.validate_regex(pattern)
        if not valid:
            raise ValueError(f"Invalid regex pattern: {err}")
        return {
            "id": rule_id, "name": name, "category": category, "severity": severity_str,
            "pattern": pattern, "explanation": explanation, "recommendation": recommendation,
        }


# ==============================================================================
# ==============================================================================
#  MODULE: VULNERABILITY KNOWLEDGE BASE
#  A CWE encyclopedia tied directly to every finding surfaced elsewhere in
#  this app — descriptions, real-world context, common causes, and a
#  concrete prevention checklist for each vulnerability class in use.
# ==============================================================================
# ==============================================================================

@dataclass
class KnowledgeBaseEntry:
    cwe: str
    name: str
    description: str
    real_world_context: str
    common_causes: List[str]
    prevention_checklist: List[str]
    further_reading: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "cwe": self.cwe, "name": self.name, "description": self.description,
            "real_world_context": self.real_world_context,
            "common_causes": self.common_causes,
            "prevention_checklist": self.prevention_checklist,
            "further_reading": self.further_reading,
        }


