with tab_code:
    render_engine_header("🔍", "Static Source Code Vulnerability Scanner", "CWE-mapped regex pattern rules across injection, crypto, secrets, deserialization, XSS, SSRF.", "🔍 Static Detection", "79 rules")
    st.caption(f"Currently loaded with {len(VULNERABILITY_RULES)} pattern rules covering injection, "
               f"crypto, secrets, deserialization, XSS, SSRF, and more (CWE-mapped).")

    scan_mode = st.radio("Input mode", ["Paste code", "Upload file(s)", "Use bundled sample"], horizontal=True)

    files_to_scan: Dict[str, str] = {}

    if scan_mode == "Paste code":
        pasted_name = st.text_input("File name (for reporting)", value="pasted_snippet.py")
        pasted_code = st.text_area("Paste source code to analyze", height=280, value=SAMPLE_VULNERABLE_CODE)
        if pasted_code.strip():
            files_to_scan[pasted_name] = pasted_code

    elif scan_mode == "Upload file(s)":
        uploaded = st.file_uploader(
            "Upload source files", accept_multiple_files=True,
            type=["py", "js", "ts", "java", "php", "c", "cpp", "go", "rb", "html", "conf", "yml", "yaml"],
        )
        if uploaded:
            for uf in uploaded:
                try:
                    files_to_scan[uf.name] = uf.read().decode("utf-8", errors="ignore")
                except Exception:
                    st.warning(f"Could not read {uf.name} as text — skipped.")

    else:
        files_to_scan["sample_app.py"] = SAMPLE_VULNERABLE_CODE
        st.code(SAMPLE_VULNERABLE_CODE, language="python")

    run_scan = st.button("🚀 Run Vulnerability Scan", type="primary")

    if run_scan and files_to_scan:
        with st.spinner("Scanning against Sentinel rule set..."):
            new_findings = code_scanner.scan_files(files_to_scan)
            st.session_state.last_findings = new_findings
            findings = baseline_manager.filter_active(new_findings)
            _scan_ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            _scan_risk = code_scanner.risk_score(new_findings)
            _scan_critical = len([f for f in new_findings if f.severity == "Critical"])
            st.session_state.scan_history.append({
                "timestamp": _scan_ts,
                "total_findings": len(new_findings),
                "risk_score": _scan_risk,
                "critical": _scan_critical,
            })
            # Persist alongside the in-memory record so this run survives
            # a restart (save_scan_record was previously defined but never
            # called anywhere — history only ever lived in session_state).
            st.session_state.sentinel_persistence.save_scan_record(
                _scan_ts, len(new_findings), _scan_risk, _scan_critical
            )
            # Evasion detection runs alongside the regular scan on every
            # Python file — a separate detection surface (see the module
            # docstring above EvasionDetector) that looks for code
            # structured to dodge scanners like this one, not for the
            # underlying vulnerability itself.
            new_evasion: List[Any] = []
            for fname, content in files_to_scan.items():
                if fname.endswith(".py"):
                    new_evasion.extend(scan_for_evasion(fname, content))
            st.session_state.evasion_findings = new_evasion
            evasion_findings = new_evasion

    if findings:
        st.markdown(f"#### Results — {len(findings)} finding(s)")
        sev_filter = st.multiselect(
            "Filter by severity", ["Critical", "High", "Medium", "Low", "Info"],
            default=["Critical", "High", "Medium", "Low", "Info"],
        )
        filtered = [f for f in findings if f.severity in sev_filter]
        df_findings = reporter.findings_to_dataframe(filtered)
        st.dataframe(
            df_findings[["rule_id", "title", "severity", "cwe", "cvss_estimate", "file_name", "line_number", "matched_snippet"]],
            use_container_width=True, height=320,
        )

        st.markdown("#### 🔬 Finding Detail Inspector")
        if filtered:
            options = [f"{f.finding_id} — {f.title}" for f in filtered]
            picked = st.selectbox("Select a finding to inspect", options)
            picked_finding = filtered[options.index(picked)]
            st.markdown("<div class='sentinel-card'>", unsafe_allow_html=True)
            st.markdown(f"##### <span class='severity-{picked_finding.severity}'>{picked_finding.severity}</span> — {picked_finding.title}", unsafe_allow_html=True)
            st.markdown(f"**CWE:** {picked_finding.cwe}  |  **Estimated CVSS:** {picked_finding.cvss_estimate}  |  **File:** `{picked_finding.file_name}:{picked_finding.line_number}`")
            st.code(picked_finding.matched_snippet, language="python")
            st.markdown(f"**Why it matters:** {picked_finding.description}")
            st.markdown(f"**Recommended remediation:** {picked_finding.remediation}")
            st.markdown("</div>", unsafe_allow_html=True)
    else:
        st.info("No findings yet — run a scan above.")

    if evasion_findings:
        st.markdown("---")
        st.markdown(f"#### 🧬 Evasion & Obfuscation Signals — {len(evasion_findings)} detected")
        st.caption(
            "A separate detection surface from the table above: these don't match a known "
            "vulnerability pattern directly — they match the STRUCTURAL SHAPE of code written to "
            "dodge scanners (dynamic dispatch, decode-then-execute, string-reassembled sinks). "
            "See the 🧬 Evasion Detector panel under Advanced Threat Ops for a standalone checker "
            "and an honest self-test of current coverage."
        )
        for ev_f in evasion_findings:
            sev_class = f"severity-{ev_f.severity}"
            st.markdown(
                f"<div class='sentinel-card'><span class='{sev_class}'>{ev_f.severity}</span> "
                f"— <b>{ev_f.title}</b><br><code>{ev_f.file_name}:{ev_f.sink_line}</code><br>"
                f"{ev_f.evidence}</div>",
                unsafe_allow_html=True,
            )
    elif files_to_scan and any(f.endswith(".py") for f in files_to_scan):
        st.caption("🧬 Evasion check: no structural dodge-the-scanner patterns detected in the scanned Python file(s).")

